local quests = WordHunterWoW_QuestDataByFlavor.classic.deDE
quests[1062] = { title = "Goblin-Eindringlinge", description = "Die von Goblins geleitete Venture Company ist in das Steinkrallengebirge umgezogen, um dort Bäume zu fällen und ganze Waldflächen zu brandroden. Die Geister dort sind außer sich vor Schmerz und Wut. Wir müssen der Venture Company Einhalt gebieten!\n\nBegebt Euch nach Nordwesten, jenseits des Hochwipfeltals, und zur Scherwindklippe. Ihr werdet dort die Goblins und ihre Gefolgsleute bei der Arbeit vorfinden - zeigt ihnen, dass die Horde eine Ausbeutung des Steinkrallengebirges nicht billigt. Zeigt es ihnen in der Sprache, die sie am besten verstehen...\n\nGewalt.", objectives = "Tötet 15 Holzfäller der Venture Co. und kehrt dann zu Seereth Stonebreak an der Grenze des Steinkrallengebirges und dem Brachland zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1063] = { title = "Die Ältestengreisin", description = "Um die Geister des Steinkrallengebirges wirklich zu beschwichtigen, müssen wir uns an die Taurenältesten wenden.\n\nIch kenne nicht viele ihrer Anführer, aber einen Namen kenne ich: Magatha. Ich habe gehört, dass sie sehr alt sein soll und sehr viel weiß. Wenn jemand die Tauren um geistige Hilfe bitten kann, dann sie.\n\nMagatha lebt in der Tauren-Hauptstadt Thunder Bluff auf der Anhöhe der Ältesten - dem Steilhang im Nordosten der Stadt. Sprecht mit Magatha und berichtet ihr von der Not im Steinkrallengebirge.", objectives = "Sprecht in Thunder Bluff mit Magatha.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1064] = { title = "Die Hilfe der Verlassenen", description = "Die Tauren sind mit dem Land verbunden, und es schmerzt mich, von der Not im Steinkrallengebirge zu hören. Ich fürchte jedoch, dass wir zunächst die Krankheit ausmerzen müssen, bevor wir das Land heilen können.\n\nIst es nicht eine glückliche Fügung, dass wir mit den Verlassenen verbündet sind? Sie wissen viel über Krankheiten. Ich glaube, sie werden uns helfen können, was das gegenseitige Vertrauen zwischen unseren Völkern stärken wird.\n\nSprecht mit Apothekerin Zamah. Sie ist eine Gelehrte und Botschafterin der Verlassenen. Ihr findet sie bei den Teichen der Visionen unterhalb der Anhöhe der Geister.", objectives = "Sprecht bei den Teichen der Visionen mit der Apothekerin Zamah.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1065] = { title = "Reise nach Tarrens Mühle", description = "Um die Venture Company aus dem Steinkrallengebirge zu vertreiben, müssen wir extreme Maßnahmen ergreifen. Extrem, aber ohne Blutvergießen.\n\nEiner meiner Kollegen hat vielleicht genau das Werkzeug, das wir benötigen. Er heißt Lydon und wohnt in Tarrens Mühle im Vorgebirge von Hillsbrad, das im weit entfernten Lordaeron liegt.\n\nUm nach Hillsbrad zu gelangen, reist mit dem Zeppelin in unsere Hauptstadt, nach Undercity. Geht von dort aus nach Norden nach Tirisfal, dann südwestlich nach Silberwald und südlich nach Hillsbrad.\n\nSucht Lydon auf und gebt ihm diese Notiz. Sie wird ihm alles erklären.", objectives = "Bringt Apotheker Lydon in Tarrens Mühle Zamahs Notiz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1066] = { title = "Das Blut Unschuldiger", description = "Ich werde ein Toxin herstellen, mit dem wir der Venture Company die Gewalt entziehen und sie schwach und sanftmütig werden lassen. Das sollte das Problem der Horde im Steinkrallengebirge lösen, meint Ihr nicht?\n\nUm das Toxin herzustellen, benötige ich jedoch das Blut Unschuldiger, eine Zutat, an die man nur schwer herankommt.\n\nGlücklicherweise beschäftigt das Syndikat, das ist eine Gruppe menschlicher Briganten in dieser Region, Schattenmagier ... und diese Magier beschaffen sich das Blut Unschuldiger für ihre eigenen unappetitlichen Machenschaften.\n\nIhr finded die Schattenmagier des Syndikats in der Burg Durnholde im Südosten.", objectives = "Bringt Apotheker Lydon in Tarrens Mühle 5 Phiolen mit dem Blut Unschuldiger.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1067] = { title = "Rückkehr nach Thunder Bluff", description = "Hier habt Ihr das Toxin. Wenn Ihr es gegen die Venture Company einsetzt, sollte es positive, vielleicht sogar ansteckende Ergebnisse erzielen. Ich muss sagen, es ist ziemlich aufregend zu sehen, dass mein Werk tatsächlich eingesetzt wird!\n\nBringt es aber erst der Apothekerin Zamah, bevor Ihr es einsetzt. Sie muss eine Anwendungsmethode für das Toxin entwickeln, um einen größtmöglichen Effekt zu erzielen.", objectives = "Bringt Apothekerin Zamah in Thunder Bluff Lydons Toxin.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1068] = { title = "Schreddermaschinen", description = "Es gibt eine Verbindung zwischen der spirituellen Magie der Schamanen und der natürlichen Magie der Druiden. Deshalb können die Schamanen auch das Flehen der Geister des Steinkrallengebirges hören. Vieles, das sie flüstern, verstehe ich nicht, aber eine Nachricht, eine Vision, ist eindeutig ...\n\nIch hatte die Vision zweier menschenähnlicher Maschinen, die auf der Scherwindklippe nordwestlich des Hochwipfeltals mit ungeheuerlicher Geschwindigkeit Bäume fällten. Diese Metallbestien müssen aufgehalten werden!\n\nIn meiner Vision trugen diese Maschinen seltsame Symbole:\n\nXT:4 und XT:9.", objectives = "Vernichtet die Schredder XT:4 und XT:9 und kehrt dann zu Seereth Stonebreak an der Grenze zwischen dem Steinkrallengebirge und dem Brachland zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1069] = { title = "Eier der Kluftmoosspinnen", description = "Omeletts aus Spinneneiern sind der letzte Schrei in Booty Bay! Das Problem ist nur... dass es in Booty Bay keine Eier gibt.\n\nDas riecht nach einer Geschäftsidee!\n\nAn der Scherwindklippe und im Sishircanyon nordwestlich im Steinkrallengebirge, lebt die Kluftmoosspinne. Bringt mir ihre Eier, dann werde ich Euch reichlich entlohnen!\n\nAn der Scherwindklippe sind die Eihaufen unter den noch verbliebenen Bäumen zu finden.\n\nIm Sishircanyon... tja, wenn Ihr einen schwachen Magen habt, solltet Ihr vielleicht nur die Eier an der Scherwindklippe sammeln...", objectives = "Bringt Mebok Mizzyrix in Ratchet 15 Kluftmooseier.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1070] = { title = "Wache halten im Steinkrallengebirge", description = "Hallo, $N.\n\nSo wie Ihr ausseht, scheint Ihr voller Reiselust zu sein. Wart Ihr schon mal im Steinkrallengebirge? Es ist ein Land, das von der Venture Company und anderen Feinden der Nachtelfen heimgesucht wird.\n\nErst neulich schickte Schildwache Wolfrunner meine Freundin Kaela Shadowspear dorthin, um zu untersuchen, was mit dem Land geschehen ist, aber ich habe seitdem nichts mehr von ihr gehört. Was mir noch mehr Sorgen macht ist, dass die Allianz sie zusammen mit einem Gnomen-Magier losgeschickt hat ... das deutet definitiv auf Probleme hin.\n\nWürdet Ihr sie suchen und mir dann Bericht erstatten?", objectives = "Sucht Kaela Shadowspear, die auf der Scherwindklippe im Steinkrallengebirge den Taleingang beobachtet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1071] = { title = "Der Aufschub des Gnoms", description = "Wisst Ihr, $N, ich bin Mitglied der Erleuchteten Vereinigung der Arkanologie, Alchimie und Ingenieurwissenschaften, und es ist mein Ziel... nein, meine PFLICHT!, den Nachtelfen zu zeigen, dass eine Mischung aus Magie, Mixturen und Mechanismen dazu beitragen kann, ihren Wald zu retten.\n\nEs ist jedoch ein Kampf gegen Windmühlen, und die Goblins vermehren sich wie die Kaninchen, wie es scheint. Ich hatte sogar nicht mal Zeit, um meine neuesten Erfindungen zu bauen!\n\nIch brauche etwas Zeit, um zu planen und zu organisieren. Dazu brauche ich jedoch Eure Hilfe bei der Eindämmung der Goblins auf der Scherwindklippe im Osten...", objectives = "Tötet 10 Holzfäller der Venture Co. und 10 Roder der der Venture Co. und kehrt dann zu Gaxim Rustfizzle im Steinkrallengebirge zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1072] = { title = "Ein alter Kollege", description = "Das Gerät, das mir vorschwebt, wird meine am weitesten entwickelte Erfindung sein. Aber wir brauchen einen speziellen Trank, wenn es funktionieren soll. Ich glaube, wir sollten uns gleich an das gute Zeug halten, immerhin könnte das unsere letzte Mission sein.\n\nUnd deshalb brauchen wir einen hochwirksamen Sprengstoff: Nitromirglyceronium.\n\nDie einzige Person, die NG-5 herstellen kann, ist ein alter Freund von mir: Lomac Gearstrip. Sucht in Tüftlerstadt nach ihm.\n\nWenn Ihr ihn überreden könnt, uns etwas NG-5 herzustellen, kann ich mich an die Platzierung meiner Geräte machen.", objectives = "Sprecht mit Lomac Gearstrip in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1073] = { title = "Stümperhaftigkeit + Chemikalien = Riesenspaß!", description = "Hahaha... Ihr braucht Nitromirglyceronium, um Goblins daran zu hindern, einen Wald zu zerstören?!\n\nEs ist mir egal, ob Ihr Gaxim kennt oder nicht... Ich würde Euch das Zeug allein schon deshalb geben, weil ich sehen will, wie Ihr oder sie in klitzekleine Fetzen explodieren.\n\nEs gibt allerdings ein Problem: Ich hab nichts mehr.\n\nAber ich sag Euch was: Bringt mir die richtigen Tränke, dann stelle ich sofort etwas für Euch her.\n\nDas Mindeste, was Ihr tun könnt, ist, mir ein paar Eurer Alchimisten-Fertigkeiten vorzuführen, bevor ich Euch eine Kostprobe meiner größten Erfindung gebe.", objectives = "Bringt Lomac Gearstrip in Ironforge 4 schwache Manatränke und 2 Elixire der Seelenstärke.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1074] = { title = "Stümperhaftigkeit + Chemikalien = Riesenspaß!", description = "Bitte sehr, Fremdling. Seid jedoch vorsichtig damit... das Zeug ist hochexplosiv.\n\nFalls Ihr wirklich ein Freund von Gaxim seid, grüßt ihn von mir. Falls nicht, dann viel Spaß beim Selbst-in-die-Luft-jagen.", objectives = "Bringt Gaxim Rustfizzle im Steinkrallengebirge das Nitromirglyceronium.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1075] = { title = "Eine Rolle von Mauren", description = "Gut, wenden wir uns jetzt dem Teil meines Planes mit der Fernzündung zu... oh, das hab ich ja noch gar nicht erklärt, stimmt's?\n\nAlso dann mal die Kurzversion: Mit etwas Magie kann ich dafür sorgen, dass der Sprengstoff hochgeht, ohne dass Ihr dabei sein müsst. Ich bastele ein Gerät zusammen, bei dem Ihr nur einen Knopf drücken müsst, damit das NG-5 explodiert, wenn Ihr bereit seid.\n\nIch brauche jedoch einen Zauber von einem Freund in Stormwind - er heißt Collin Mauren. Ihr findet ihn im dortigen Magierviertel. Er ist ein Mensch, daher solltet Ihr ihn kaum verfehlen können.", objectives = "Sucht Collin Mauren in Stormwind auf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1076] = { title = "Teufel in Westfall", description = "Ah, ich glaube, ich hab's. Ein Nachrichtenzauber... Er dürfte den Effekt haben, nachdem er sucht.\n\nIch muss eine Rolle herstellen, auf die der Zauber geprägt ist. Dazu benötige ich die Überreste eines Staubteufels.\n\nWarum geht Ihr nicht nach Westfall und sucht eine dieser elenden Kreaturen, während ich den Rest der Komponenten sammle? Sie sind gefährlich, aber ich bin mir sicher, dass Ihr schon damit klarkommt, zumal Ihr sogar gewillt seid, an einem von Gaxims Experimenten teilzunehmen.\n\nIch werde hier sein, wenn Ihr zurückkommt.", objectives = "Bringt Collin Mauren in Stormwind die Überreste eines Staubteufels.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1077] = { title = "Speziallieferung für Gaxim", description = "Bitte sehr, $n. Das sollte funktionieren.\n\nBitte grüßt Gaxim von mir, wenn Ihr ihn das nächste Mal seht. Ich freue mich schon so darauf, von diesem Abenteuer zu hören, wenn Ihr es überstanden habt.\n\nLebt wohl.", objectives = "Bringt Gaxim Rustfizzle im Steinkrallengebirge die Rolle der Nachrichtenübermittlung.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1078] = { title = "Suche für Mauren", description = "Immer wieder fragen mich Reisende über das Steinkrallengebirge aus. Scheint ein beliebter Ort unter Abenteurern zu sein; spielt keine Rolle, ob man Flügeldrachen oder Elementare sucht, oder ob man Geschäfte mit der Venture Company machen will.\n\nIm verbrannten Tal tief im Steinkrallengebirge gab es mal eine Basiliskenart, deren Schuppen, wenn man sie zu Staub zermahlte, ein wunderbares Reagenz für einige der Zauber ergab, die ich ersonnen habe.\n\nWenn diese Basilisken noch leben, hätte ich liebend gern ein paar ihrer Schuppen.\n\nLasst Euch Zeit, ich hab keine Eile, aber ich kann Euch gut bezahlen.", objectives = "Bringt Collin Mauren in Stormwind 8 kristallisierte Schuppen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1079] = { title = "Geheimoperation Alpha", description = "Das ist es, $n. Seht genau hin. Die Geräte sind fertig und einsatzbereit.\n\nNehmt diese Blätter - sie erklären mehr über die Zünder und den Sprengstoff und wo Ihr ihn platzieren solltet.\n\nDenkt daran, der Erfolg Eurer Mission hängt nicht davon ab, wie viel Schaden Ihr anrichtet. Der Erfolg von Plan Alpha hängt davon ab, dass Ihr die Ingenieurspläne der Venture Company aus dem Sägewerk südlich des Felskesselsees holt.", objectives = "Holt die Ingenieurspläne der Venture Company aus dem Sägewerk auf der Scherwindklippe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1080] = { title = "Geheimoperation Beta", description = "Plan Beta funktioniert genau wie Plan Alpha, $n.\n\nWir stiften Verwirrung und stehlen dann ihre wertvollen Dokumente.\n\nWir müssen unbedingt diese Dokumente haben... vergesst das nicht.\n\nDie Blätter, die Ihr bereits habt, zeigen Euch, wo Ihr den Sprengstoff platzieren müsst. Kommt mir nur heil und mit diesen Dokumenten zurück...", objectives = "Holt die Dokumente der Venture Company aus der Scherwindmine am Ostende der Scherwindklippe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1081] = { title = "Tyrandes Empfang", description = "$N, ich bin mir sicher, dass Tyrande Whisperwind Euch persönlich für Eure Teilnahme an dieser Mission danken wollen wird.\n\nEs mag auf den ersten Blick zwar nicht so aussehen, aber Ihr habt dazu beigetragen, etwas in Gang zu setzen, das unsere Position im Steinkrallengebirge erheblich stärken wird.\n\nFalls Ihr Euch als unseren Verbündeten im Kampf gegen diese Gräueltaten betrachtet, sucht Tyrande im Tempel des Mondes in Darnassus auf.", objectives = "Sucht Tyrande Whisperwind in Darnassus auf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1082] = { title = "Neuigkeiten für Schildwache Thenysil", description = "$N, Ihr habt Großes geleistet, indem Ihr uns hier geholfen habt.\n\nDie Schildwachen von Ashenvale werden Euch reichlich belohnen, wenn Ihr ihnen mitteilt, dass Gaxim und ich noch am Leben sind. Sagt ihnen, dass wir beim Aufhalten der Venture Company und der Heilung des Landes gute Fortschritte machen.\n\nSucht Tara Thenysil in Astranaar auf. Sie wird sich freuen, dass Ihr mit guten Neuigkeiten kommt.", objectives = "Kehrt zu Schildwache Thenysil in Ashenvale zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1083] = { title = "Wütende Geister", description = "Ich weiß nicht genau, was die Venture Company dem Tal angetan hat, aber es ist offensichtlich, dass es von den dortigen Kreaturen überwältigt wurde.\n\nSie steckten den Wald in Brand und benutzten ihre zerstörerischen Erfindungen, um so viel wie möglich des Tals zu zerstören.\n\nIn ihrer Dummheit haben sie jedoch auch noch etwas anderes entfesselt: brennende Geister, Elementare der Flammen, der Steine und der Wut.\n\nDas Land wird Elune nicht mehr lächeln sehen, solange diese Kreaturen frei herumstreifen.\n\nBringt mir ihre glimmenden Überreste, um mir zu zeigen, dass Ihr sie dezimiert habt.", objectives = "Bringt Kaela Shadowspear im Steinkrallengebirge 8 glimmende Überreste der Feuerelementare des verbrannten Tals.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1084] = { title = "Verletzte Urtume", description = "Es scheint mir offensichtlich, dass die Beschützer des Tales - die Treants - irgendetwas damit zu tun hatten, dass die Venture Company zurückgeschlagen wurde. Leider wurden selbst diese einst so großen Wächter jetzt verderbt.\n\nGaxim glaubt, dass ihre Verderbnis irgendwie mit den Waffen zusammenhängt, die die Goblins während ihres Rückzuges benutzten.\n\nIch bat ihn, eine Probe von einem verwundeten Treant zu nehmen und sie zu untersuchen, um herauszufinden, ob das wirklich stimmt.\n\nBringt mir ein paar Späne, damit der Gnom mehr darüber herausfinden kann ...", objectives = "Bringt Kaela Shadowspear im Steinkrallengebirge ein Stück eines zerfressenen Spans.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1085] = { title = "Wache halten im Steinkrallengebirge", description = "Die Lage hier im Steinkrallengebirge ist offensichtlich düster, wenn Nachtelfen und Gnome zusammenarbeiten.\n\nDie Venture Company hat das Land verwüstet und ich habe einen Großteil meines Leben damit zugebracht, der Zerstörung ein Ende zu setzen.\n\nMan sollte Gaxim nicht vorschnell beurteilen; er versteht die Notwendigkeit, warum wir zusammenarbeiten müssen.\n\nWenn Ihr uns helfen wollt, sprecht zunächst mit Gaxim.\n\nEs tut mir leid, dass ich Euch jetzt noch nicht mit guten Neuigkeiten zu Tara zurückschicken kann. Aber vielleicht schon bald.", objectives = "Sprecht mit Gaxim.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1086] = { title = "Der Flugapparathafen", description = "Das Toxin ist bereit. Jetzt muss es nur noch ausgeliefert werden. Ihr, $n, müsst es ausliefern.\n\nDie Venture Company muss irgendwelche Mittel und Wege haben, Nachrichten und leichte Fracht zwischen ihrem Hauptquartier und dem Betrieb im Steinkrallengebirge hin- und herzuschicken. Es könnte ein kleiner Flugplatz sein - nicht groß genug für einen Zeppelin, aber vielleicht für einen Flugapparat. Ihr müsst die Gebiete, die von der Venture Company kontrolliert werden, durchsuchen und diesen Flugplatz finden, falls er existiert. Solltet Ihr ihn finden, platziert das Toxin dort.\n\nPlatziert es und lauft, was Ihr könnt.", objectives = "Bringt den Toxinvernebler zum Flugplatz der Venture Company und kehrt dann zu Apothekerin Zamah zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1087] = { title = "Cenarius' Vermächtnis", description = "Ihr könnt Euch nicht vorstellen, wie groß mein Hass auf dieses elende Land ist. Solche Leute wie Cenarius und die Kaldoreidruiden auf dem Gipfel benutzen ihre lächerlichen Mächte, um den Magiefluss zu stoppen, sogar noch so weit von ihrem lächerlichen Besitz entfernt ... ihren geliebten Wäldern.\n\nIch wünschte, ich könnte nach Jaedenar zurückkehren und im Fluss der Magie baden, aber mein Meister erlaubt mir erst dorthin zurückzukehren, wenn meine Arbeit getan ist.\n\nZweifellos liebt Ihr die Nachtelfen und ihre Verbündeten genauso wenig wie ich. Helft mir, dann haben wir vielleicht beide etwas davon.", objectives = "Tötet für Brealyn Firehand in Sonnenfels 4 Söhne des Cenarius, 4 Töchter des Cenarius und 4 cenarische Botaniker.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1088] = { title = "Ordanus", description = "Sie dachten, dass man den Fluss der Magie zum Erliegen bringen könnte. Sie haben sich geirrt. Sie dachten, dass sie Ordanus verstecken könnten, aber ich will seinen Kopf!\n\nDie Magie gewährt mir Durchblick. Ja... da ist er. Ein Scheideweg... auf dem Wipfel eines großen Baumes in Ashenvale. Ein Name... Raynewood. Einer der ältesten Söhne des Waldgottes. Sie haben ihn aus dem Wipfel geschleust, bevor ich ihn finden konnte, aber ihm läuft langsam die Zeit davon.\n\nBringt ihn mir, dann teile ich ein großes Geschenk mit Euch.", objectives = "Bringt Braelyn Firehand in der Nähe von Sonnenfels Ordanus' Kopf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1089] = { title = "Der Höhlenbau", description = "Die Druiden errichteten den Krallenbau auf dem Steinkrallengipfel, in dem sie viele mächtige Gegenstände aufbewahren.\n\nSie haben sich ein komplexes Schema ausgedacht, damit sie nicht in die falschen Hände gelangen.\n\nGlücklicherweise konnte ich einem von ihnen... ein paar Details entlocken.\n\nVersteckt in einer kleinen Laterne am Eingang des Baus werdet Ihr den Torhüterschlüssel finden. Damit könnt Ihr die Behälter öffnen, die über den ganzen Bau verteilt sind. Mit den Gegenständen aus diesen Behältern wiederum könnt Ihr ihren Hort öffnen, der sich in einem der zentralen Bereiche befindet.", objectives = "Begebt Euch zum Höhlenbau auf den Steinkrallengipfel. Benutzt den Torhüterschlüssel, um Euch die versteckten Gegenstände der Druiden zu besorgen. Benutzt diese Gegenstände, um den Hort des Krallenbaus zu öffnen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1090] = { title = "Gerenzos Befehle", description = "Wisst Ihr, ich war hier einst die zweitwichtigste Person. Das hat sich alles geändert, als Gerenzo hier übernahm. Hat meinen Boss Ziz Fizziks gefeuert und mich zum Arbeiten nach unten in die Minen geschickt. Ziz sagte mir aber, dass ich hier bleiben und Informationen sammeln solle. Sein neuer Boss wird uns gut bezahlen, wenn wir rausfinden, was Gerenzo plant.\n\nEgal, was ich weiß ist, dass Gerenzo befohlen hat, dass Riesenmengen von diesem gold-grünen Erz abgebaut werden sollen. Ich hol Euch eine Probe, damit Ihr sie Ziz bringen könnt, aber Ihr müsst Euch vor Patrouillen hüten, während ich es hole.", objectives = "Nehmt das rätselhafte Erz, nachdem Piznik es fertig abgebaut hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1091] = { title = "Kaelas Update", description = "$n, bringt Kaela diese Briefe. Ich bin mir sicher, dass sie das interessiert. Oder zumindest die Schildwachen.\n\nErzählt Ihr unbedingt, wie erfolgreich wir waren und dass wir es ohne ein bisschen Magie nie geschafft hätten.", objectives = "Bringt Kaela Shadowspear die Dokumente der Venture Company.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1092] = { title = "Gerenzos Befehle", description = "Ich glaube, ich sollte auch langsam darüber nachdenken, hier zu verschwinden. Es wird nicht lange dauern, bis die da oben erfahren, was hier gelaufen ist, und ich bin sicher, dass die keinen großen Wert darauf legen, mich wiederzusehen.\n\nIch schleich mich raus und treff mich mit Ziz. Hoffentlich kann er mir einen neuen Job besorgen!\n\nIch werde versuchen, hier ein bisschen Ordnung zu schaffen, aber Ihr solltet die Erzprobe sofort zu Ziz bringen. Er sagte mir, dass er irgendwo an der Westseite der Scherwindklippe sein Lager aufgeschlagen hat. Viel Glück.", objectives = "Bringt Ziz Fizziks im Steinkrallengebirge das unbekannte Erz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1093] = { title = "Superschnitter 6000", description = "Schrecklich, was die Venture Company hier getan hat, was? Was haben die sich dabei gedacht? Eine Goblin-Firma, die einen Gnom anheuert!\n\nEin Glück für mich, dass Sputtervalve ein Genie erkennt, wenn es vor ihm steht. Hat mich eingestellt, gleich nachdem ich gefeuert wurde!\n\nSagte mir, sie wollten eine riesige Holzfällmaschine bauen, und Sput möchte, dass ich für ihn die Pläne dazu stehle. Leider wird Gerenzo - dieser verdammte Gnom - mich umlegen, sobald er mich sieht ... würdet Ihr vielleicht die Pläne für mich stehlen? Ihr solltet sie bei einem ihrer Maschinenführer finden.", objectives = "Besorgt für Ziz Fizziks im Steinkrallengebirge die Blaupausen für den Superschnitter 6000.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1094] = { title = "Weitere Instruktionen", description = "In diesem Umschlag befinden sich alle Informationen, die ich mir schnappen konnte, bevor sie mich vor die Tür setzten... Interne Dokumente der Venture Company, ein paar Handbücher, technisches Zeugs... Oh, und natürlich die Blaupausen für den Superschnitter 6000.\n\nSputtervalve hat sich bei Ratchet im Brachland niedergelassen. Sollte nicht schwer sein, ihn zu finden. Er ist ein kleiner, grüner Kerl.", objectives = "Bringt Sputtervalve im Brachland den versiegelten Umschlag.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1095] = { title = "Weitere Instruktionen", description = "Die Tatsache, dass die Venture Company diesen Gnom angestellt hat, hat in Undermine für einiges Aufsehen gesorgt. Die Handelsbarone finden es nicht gut, dass Razdunk mit Gerenzo gemeinsame Sache macht.\n\nRiddlevox hat mich gebeten, mich um das Problem zu kümmern und ich bin mir sicher, dass einer oder zwei dieser Handelsbarone ihn dazu angewiesen haben. Natürlich hat mir der Direktor das nicht erzählt. Sagen wir einfach, ich hätte so eine Ahnung.\n\nWie dem auch sei, Gerenzo muss entfernt werden und es wäre eine passende Prüfung, das Fizzik erledigen zu lassen.", objectives = "Bringt Ziz Fizziks im Steinkrallengebirge die neuen Befehle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1096] = { title = "Gerenzo Pfeifzang", description = "Ich habe Gerenzo einmal getroffen, und lasst mich Euch eines sagen, er ist nicht gerade eine Schönheit. Sein Fleisch sieht aus, als würde es faulen. Dazu hat er noch überall an seinem Körper Metallteile und Zeugs angeflanscht und sogar einige seiner Körperteile durch mechanische ersetzt.\n\nNordöstlich von hier, weit oberhalb des Felskesselsees in der Nähe des Wasserrades beaufsichtigt Gerenzo die gesamte Stätte. Ich könnte mich unmöglich bis da hinauf durchkämpfen und schon gar nicht mich mit Gerenzo anlegen ... Aber Ihr seht aus, als könntet Ihr es schaffen.\n\nWenn Ihr ihn für mich tötet, soll es Euer Schaden nicht sein!", objectives = "Bringt Ziz Fizziks im Steinkrallengebirge Gerenzo Wrenchwhistles mechanischen Arm.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1097] = { title = "Elmores Aufgabe", description = "In Stormwind gibt es einen Zwergen-Waffenschmied namens Grimand Elmore, der mal angedeutet hat, dass er Hilfe bei einer Lieferung bräuchte. Ich glaube, er möchte ein Paket in seine Heimat im Norden schicken.\n\nIhr habt da ein paar schöne kräftige Beine! Falls Ihr also an ein wenig Beinarbeit interessiert seid, sprecht mit Grimand. Wir könnten Euch hier unten brauchen, aber wir müssen auch unsere Bande mit den Zwergen stärken.\n\nIhr findet Grimand Elmore im Waffenladen im Zwergendistrikt von Stormwind, im nordöstlichen Teil der Stadt.", objectives = "Sprecht mit Grimand Elmore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1098] = { title = "Todespirscher in Shadowfang", description = "Als Vorbereitung auf einen Überfall auf Shadowfang wurden zwei Todespirscher in die Burg geschickt, um Informationen zu sammeln. Das war vor mehreren Tagen und sie sind noch nicht wieder zurück, aber wir brauchen ihren Bericht, wenn wir auf einen erfolgreichen Angriff hoffen wollen!\n\nDas ist Eure Aufgabe, $N. Geht zu Burg Shadowfang im Süden und sucht die Todespirscher Adamant und Vincent. Findet sie und helft ihnen, falls es erforderlich ist.\n\nDiese Mission ist nicht nur gefährlich, sondern auch lebenswichtig, $N. Versagt bitte nicht.", objectives = "Sucht die Todespirscher Adamant und Vincent.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1100] = { title = "Lonebrows Tagebuch", description = "Ihr öffnet langsam das verwitterte Tagebuch des Henrig Lonebrow...", objectives = "Lest Henrig Lonebrows Tagebuch.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1101] = { title = "Die Greisin des Krals", description = "Armer Heralath! Und dieser Zwerg... Lonebrow. Was war er doch für eine mutige Seele.\n\nSo viel Heldenmut darf nicht umsonst gewesen sein. Diese Greisin... Charlga Razorflank... muss aufgehalten werden.\n\nSicher, es wird gefährlich werden, den Kral zu bespitzeln. Wir haben keine Zeit, um Darnassus zu informieren. $n, stellt eine Gruppe zusammen, um die Greisin zu erschlagen.\n\nBringt mir Razorflanks Medaillon zum Beweis ihres Ablebens.", objectives = "Bringt Falfindel Waywarder in Thalanaar Razorflanks Medaillon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1102] = { title = "Ein schreckliches Schicksal", description = "Es war edel von unserem Anführer Cairne, unser Volk hier in Thunder Bluff zu vereinen.\n\nIch kann jenen jedoch nicht vergeben, die uns so leicht aus dem Land unserer Vorfahren vertrieben haben. Jahrhundertelang lebte mein Volk im südlichen Brachland. Das Land war uns heilig. Aber wir wurden von zahllosen Feinden vertrieben.\n\nEin schreckliches Schicksal erwartet die Greisin Charlga Razorflank, die im Kral von Razorfen eine abscheuliche Armee zusammenzieht.\n\nBringt mir Razorflanks Herz, damit ich in Frieden sterben kann, $n.", objectives = "Bringt Auld Stonespire in Thunder Bluff Razorflanks Herz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1103] = { title = "Ruf des Wassers", description = "Seid gegrüßt, $g Bruda:Schwesta;! Seid auch Ihr gekommen, um das Wasser hier zu läutern und Islen Euer Wissen zu beweisen?\n\nIch habe den verderbten Wassergeist gerade selbst bezwungen und bin grad dabei, die Armschienen un' verbleibenden Wassertropfen in die Kohlenpfanne zu geben.\n\nWas'n das? Ahhh. Tiev versteht nur zu gut, wenn wat falsch läuft. Tja, Tiev kann Euch echt helfen, wenn Ihr den Wassergeist wieda seh'n wollt.\n\nBringt mir 'in Wassersapta von Islen als Beweis, dass Ihr bereit seid, un' ich bin bereit, meinen Teil beizutrag'n.", objectives = "Bringt Tiev Mordune im Silberwald ein Wassersapta, wenn Ihr nicht mit der schwachen Wassermanifestation gesprochen habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1104] = { title = "Salziges Gift", description = "Ich habe so viele Pläne für unseren Raketenwagen! So viele! Und ich muss sie alle ausprobieren!!!\n\nIch arbeite gerade an einem neuen Treibstoff; an einem, der wirklich, wirklich, wirklich heiß ist! Die Mixtur stimmt zwar noch nicht ganz, aber ich glaube, ich weiß, was noch fehlt...\n\nDie Skorpide, die die Schimmernde Ebene durchwandern, haben ein Gift mit Unmengen Salz darin. Es ist einzigartig! Und es ist genau das, was ich brauche!\n\nBringt mir das Gift und vertraut mir: unser Wagen wird fliegen!", objectives = "Bringt Fizzle Brassbolts in der schimmernden Ebene 6 Einheiten salziges Skorpidgift.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1105] = { title = "Gehärtete Schalen", description = "Mein Bruder arbeitet an einem neuen Treibstoff für seinen Raketenwagen. Er ist brillant, ehrlich. So brillant, dass... Ich glaube, der neue Treibstoff, den er da entwickelt, ist stark genug, um sich durch das Chassis des Wagens zu fressen!\n\nIch würde gern die Treibstofftanks verstärken, bevor das passiert.\n\nDie Schildkröten draußen auf der Ebene haben sehr starke Panzer. Ich möchte daraus neue Tanks für unseren Raketenwagen bauen. Tanks, die den neuen Treibstoff meines Bruders aushalten.\n\nIhr seht mir verantwortungsbewusst genug aus. Holt Ihr mir solche Panzer?", objectives = "Bringt Wizzle Brassbolts in der schimmernden Ebene 9 gehärtete Schildkrötenpanzer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1106] = { title = "Martek der Verbannte", description = "Ich entwickle einen neuen Motor, mit dem der Wagen so schnell wie der Wind wird! Schnell genug, um zu fliegen, ich weiß es! Ich muss nur ein paar Kolben herstellen, die sehr, sehr große Belastungen aushalten. All meine bisherigen Versuche sind fehlgeschlagen, weil ich die Kolben einfach nicht robust genug herstellen kann!\n\nAber es gibt jemanden, der wissen könnte, wie es geht.\n\nSein Name ist Martek der Verbannte. Er ist ein großartiger Schmied und weiß mehr über Metall als alle anderen. Bringt ihm diesen Brief, ich weiß, dass er helfen kann!\n\nAber er lebt weit, weit weg - in Azeroth, im Ödland, in einem Lager, zusammen mit einem Goblin!\n\nSucht ihn!", objectives = "Bringt Martek dem Verbannten im Ödland Fizzles Brief.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1107] = { title = "Verkrustete Schwanzflossen", description = "Unser Raketenwagen ist das schnellste, was es auf der Ebene gibt! So schnell, dass... ich fürchte, die Reibung reißt ihn auseinander!\n\nUm das zu verhindern, muss ich einen Stoff entwickeln, der die beweglichen Teile des Wagens überzieht. Er muss hart sein, aber nicht spröde, und er muss resistent gegen Salzkorrosion sein, sonst wird der Wagen, während er sich in der Schimmernden Ebene befindet, zerfressen.\n\nHabt Ihr schon mal vom Finsteren Riff gehört, $n? Es liegt vor der Küste des Schlingendorntals. Dort leben Salzschuppenmurlocs, deren Schwanzflossen unabdingbare Zutaten zu meinem Stoff sind.", objectives = "Bringt Fizzle Brassbolts in der schimmernden Ebene 10 verkrustete Schwanzflossen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1108] = { title = "Indurium", description = "Ich bin nicht hier draußen, weil ich mich vor Leuten verstecken will. Das Ödland ist reich an Metall, $N, wenn man den Mut hat, es sich zu holen.\n\nDas Metall heißt Indurium, und wie das Schicksal so spielt, soll es angeblich hohen Widerstand gegen Hitze und Belastung bieten. Das könnte genau das Richtige für Fizzles Wagen sein.\n\nAber wir sollten sichergehen. Bringt mir eine Indurium-Probe, dann kann ich seine Eigenschaften testen.\n\nEchtes Induriumerz liegt tief drinnen in Uldaman, aber die Steingrufttroggs des Ödlandes tragen manchmal Späne davon mit sich herum. Bringt mir diese Späne.", objectives = "Bringt Martek dem Verbannten im Ödland 10 Induriumspäne.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1109] = { title = "Go, Go, Guano!", description = "Wie Ihr seht, $N, befassen wir uns mit einigen sehr... interessanten Experimenten in der Königlichen Apothekervereinigung.\n\nAls Meister hier ist es meine Aufgabe, die anspruchsvollsten unserer alchimistischen Versuche zu überwachen. So viel Arbeit und nur so wenig Zeit!\n\nIhr seht weit gereist aus, $C. Vielleicht könnt Ihr mir helfen.\n\nIch brauche eine rare Substanz. Es ist dieses widerliche Zeug, das von einer raren Fledermausart stammt, die man nur in einem Dreckloch namens Kral von Razorfen findet. Bringt mir den Guano der Kral-Fledermäuse, damit wir mit unserer Arbeit beginnen können...", objectives = "Bringt dem Apothekermeister Faranell in Undercity 1 Häufchen Kral-Guano.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1110] = { title = "Raketenwagenteile", description = "Hi-hi, bei den vielen Rennen, die hier stattfinden, ist es nicht verwunderlich, wenn dabei ein paar Unglücksfälle passieren. Wenn man sich in der Schimmernden Ebene umschaut, sieht man ständig Spuren vergangener Unfälle - überall liegen Teile von Raketenwagen herum.\n\nUnd diese Teile bedeuten für die Gnome und Goblins bares Geld. Sie suchen ständig nach weiteren neumodischen Apparaten, um sie an ihre Autos anzubauen.\n\nAlso zieht los und bringt mir die Teile. Bringt mir einen Haufen und ich werde Euch gut bezahlen.", objectives = "Bringt 30 Raketenwagenteile zu Kravel Koalbeard in der schimmernden Ebene.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1111] = { title = "Werftmeister Dizzywig", description = "Mein Job ist es, den Leuten zu beschaffen, was sie möchten, und diese Gnome da drüben möchten Teile bestellen. Ihre Teile wurden vor einer Woche nach Ratchet geschickt, aber es war mir nicht möglich, dorthin zu reisen.\n\nAlso, seid Ihr bereit, mir die Kleinarbeit abzunehmen? Geht nach Ratchet und gebt diese Teile-Bestellung an Werftmeister Dizzywig - er wird wahrscheinlich bei den Docks sein.\n\nWenn Ihr das macht, habe ich weitere Aufträge für Euch.\n\nAufträge, bei denen eine Menge Profit rausspringen kann ...", objectives = "Bringt Kravels Teile-Bestellung zu Werftmeister Dizzywig in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1112] = { title = "Teile für Kravel", description = "Hier ist Kravels Paket, $n. Und wenn Ihr es zustellt, sagt ihm bitte... wenn er weitere spezielle Lieferungen möchte, dann muss er bezahlen!", objectives = "Bringt Kravels Teile zu Kravel Koalbeard in der schimmernden Ebene.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1113] = { title = "Herzen des Eifers", description = "Warum ich eine rare Art von Guano benötige, fragt Ihr Euch? Also bei diesem Experiment möchte ich wissen, wie zwei diametral entgegengesetzte chemische Substanzen aufeinander wirken, besonders wenn beide mit einem höchst toxischen Agens kombiniert werden, um die ... garstigsten Resultate zu erzielen.\n\nIn der Nordostspitze von Tirisfal liegt das Scharlachrote Kloster. Dort versammeln sich die wahnsinnigen Jünger des Scharlachroten Kreuzzuges. Tötet sie und bringt mir ihre übereifrigen Herzen.\n\nUnser Gebräu wird äußerst tückisch sein!", objectives = "Apothekermeister Faranell in Undercity möchte 20 Herzen des Eifers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1114] = { title = "Lieferung für die Gnome", description = "Jetzt, wo ich habe, was ich brauche, gebt diese Teile Fizzle Brassbolts. Er wartet schon lange darauf - ich bin sicher, das kleine Teil, das ich behalten habe, wird er nicht vermissen...\n\nUnd ich würde ihn auch nicht darauf hinweisen. Es war klein und wertlos.\n\nGlaubt mir.", objectives = "Bringt die empfindlichen Autoteile zu Fizzle Brassbolts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1115] = { title = "Der Gerüchteverbreiter", description = "Jetzt, da wir diesen Dienst für die Gnome geleistet haben, wird es Zeit, den Goblins einen Gefallen zu tun! \n\nIch habe gehört, dass der Goblin-Rennfahrer Nazz Steamboil diesen Namen nicht immer getragen hat. Ich frage mich, weshalb er ihn änderte. Ob es wohl ein Geheimnis ist und... wie viel ihm dieses Geheimnis wert ist.\n\nWenn jemand die Wahrheit kennt, dann Krazek aus Booty Bay an der Südspitze des Schlingendorntals. Sprecht mit Krazek und fragt ihn nach unserem Goblin-Rennfahrer.\n\nWenn Ihr nützliche Informationen aus ihm herausbekommt, springt vielleicht Profit für uns raus.", objectives = "Sprecht mit Krazek in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1116] = { title = "Traumstaub im Sumpf", description = "Es ist ein großer Gefallen, diese Informationen über Nazz zu beschaffen, $n. Ja, ein großer Gefallen. Aber Ihr habt den weiten Weg von der Schimmernden Ebene auf Euch genommen... seid Ihr bereit, noch etwas weiter zu reisen?\n\nIhr könntet doch etwas für mich besorgen, während ich Kontakt mit meinen Informanten aufnehme, hm?\n\nHmm... was könnte es denn sein? Wie wäre es mit Traumstaub von den Großdrachenwelpen und Wyrmkin aus den Sümpfen des Elends? Ja, ich hätte gern etwas Traumstaub für meinen Schnupftabakbeutel!\n\nBringt ihn mir, $n, und ich gebe Euch die gewünschten Informationen.", objectives = "Bringt 10 Körnchen Traumstaub zu Krazek in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1117] = { title = "Gerüchte für Kravel", description = "Ich musste einige Gefälligkeiten erweisen, eine rare Flasche Elfenwein herschenken und mir selbst einiges zusammenreimen! Aber ich habe die Informationen, die Ihr sucht.\n\nHier, ich habe einen Brief mit einigen sehr interessanten Infos über Euren Freund Nazz Steamboil verfasst. Macht damit, was Ihr wollt - für mich wäre es zu gefährlich, ihn zu benutzen.\n\nSagt nur keinem, woher Ihr das habt!", objectives = "Bringt die Goblin-Gerüchte zu Kravel Koalbeard in der schimmernden Ebene.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1118] = { title = "Zurück nach Booty Bay", description = "$N, Ihr seid ein $C, dem ich trauen kann. Ihr werdet den Auftrag erledigen und die Klappe halten.\n\nIch habe einen neuen Plan geschmiedet. Er ist riskant, aber wenn er funktioniert, könnten wir beide gut absahnen! Und ich glaube, Ihr seid der Richtige, um das durchzuziehen.\n\nAls Erstes müsst Ihr nach Booty Bay zurückkehren. Nun, ich bitte um Verzeihung, $N. Ich weiß, meine letzte Aufgabe führte Euch dorthin. Aber sprecht diesmal mit Crank Fizzlebub.\n\nGebt ihm diesen Brief. Und wenn er um Unterstützung bittet, dann tut, was Ihr könnt, um ihm zu helfen. Es wird sich lohnen.", objectives = "Bringt Kravels Plan zu Crank Fizzlebub in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1119] = { title = "Zanzils Mixtur und Fools Starkbier", description = "Ich habe herausgefunden, wie man aus Zanzils Mixtur mit Starkbier ein mächtiges Getränk macht. Fools Starkbier. Und ich glaube, genau das braucht Kravel. Probiert es einfach mal aus und lasst mich wissen, wie es wirkt.\n\nUnd behaltet das Zeug nicht zu lange unbenutzt, $n. Zanzils Mixtur hat eine seltsame Wirkung auf die Hefe des Starkbiers und regt sie heftig an. Sie bleibt nicht ewig frisch.", objectives = "Bringt Fools Starkbier zu Kravel in der schimmernden Ebene zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1120] = { title = "Die Gnome betrunken machen", description = "Wir müssen Fools Starkbier an einem aus der Boxencrew ausprobieren. Wenn Ihr es an den Gnomen erproben wollt, hier - nehmt das Starkbier und gebt es dem Gnomen-Boxenboss.\n\nUnd wartet nicht zu lange. Das Starkbier wird mit der Zeit schlecht.", objectives = "Bringt Fools Starkbier zum Gnomen-Boxenboss.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1121] = { title = "Die Goblins betrunken machen", description = "Wir müssen Fools Starkbier an einem aus der Boxencrew ausprobieren. Wenn Ihr es an den Goblins erproben wollt, hier - nehmt das Starkbier und gebt es dem Goblin-Boxenboss.\n\nUnd wartet nicht zu lange. Das Starkbier wird mit der Zeit schlecht.", objectives = "Bringt Fools Starkbier zum Goblin-Boxenboss.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1122] = { title = "Meldet Euch bei Fizzlebub", description = "Fools Starkbier hat astrein gewirkt! Ich habe beim nächsten Rennen gesetzt... hoffen wir, das Team, das Ihr betrunken gemacht habt, hat sein Auto nummeriert!\n\nBleibt nur noch eine Aufgabe für Euch - bringt diese Notiz zu Crank Fizzlebub in Booty Bay. Er wird von dem erfolgreichen Test wissen wollen.\n\nHoffentlich bekommen wir mehr von Fools Starkbier für künftige Rennen!", objectives = "Bringt den Bericht über Fools Starkbier zu Crank Fizzlebub in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1123] = { title = "Rabine Saturna", description = "Für diese Aufgabe sucht Majordomus Rabine Saturna für Bewahrer Remulos in Moonglade Unterstützung bei der Erforschung des riesigen Ödlandes weit im Westen von Tanaris und Un'Goro. Er lebt in Nighthaven, dem Hauptort von Moonglade.\n\nVorher möchte ich Euch jedoch noch von der Wichtigkeit Eurer Anwesenheit in Kenntnis setzen. Es gibt zunehmend Spannungen zwischen den Nachtelfen von Darnassus und dem Zirkel des Cenarius in Moonglade. Lasst Euch nicht von völkischer Engstirnigkeit beirren und verlasst Euch auf die Weisheit Eurer Vorfahren, wenn Ihr dort mit dem Zirkel zu tun habt, $N. Viel Glück.", objectives = "Sprecht mit Rabine Saturna im Dorf Nighthaven in Moonglade. Moonglade liegt zwischen dem Teufelswald und Winterspring, und Ihr erreicht es über den Pfad, der aus der Holzschlundfeste herausführt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1124] = { title = "Einöde", description = "Westlich des Un'Goro Kraters entlang des nordwestlichen Grats liegt ein raues Ödland - Silithus. Nur wenige wissen, dass sich hier vor Urzeiten ein Krieg zwischen den Nachtelfen und einer bösartigen, außerirdischen Macht abgespielt hat. Das Böse wurde versiegelt, aber jetzt befürchten wir, dass Kräfte am Werk sind, um diesen... unaussprechlichen Horror wieder zu entfesseln.\n\nSprecht mit Layo Starstrike, einem unserer Agenten in Silithus. Sucht nach ihm in Heldenwacht, der letzten Ruhestätte der Gefallenen des Ödlandes. Gebt Ihm diesen Brief, damit erwerbt Ihr sein Vertrauen.", objectives = "Sprecht in der Nähe des Friedhofs Heldenwacht in Silithus mit Layo Starstrike und zeigt ihm Rabines Brief.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1125] = { title = "Die Geister vom Südwindposten", description = "Südwestlich von uns liegt ein tragischer Schauplatz - die Ruinen vom Südwindposten. Dort sollten wir mit unserer Arbeit beginnen, $N.\n\nNach allem, was wir wissen, war dieses Dorf einst ein Stützpunkt der Nachtelfen für Operationen in Silithus. In der Zwischenzeit wurde es längst von den Silithidschwärmen überrannt, die die Wüsten durchziehen. Ich vermag mir den Horror kaum vorzustellen, als die Zerstörung des Dorfs begann...\n\nDie gequälten Geister gefallener Druiden und Schildwachen wandern ziellos durch die Ruinen. Erforscht diesen Ort und befreit die Seelen dieser unglücklichen Kreaturen, wo immer es erforderlich ist.", objectives = "Befreit die Geister von 8 gequälten Druiden und 8 gequälten Schildwachen beim Südwindposten und kehrt dann zu Layo Starstrike auf den Friedhof Heldenwacht in Silithus zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1126] = { title = "Schwarmbau im Turm", description = "Wir müssen uns um den Schwarmbau beim Südwindposten kümmern, und ich glaube, ich weiß auch schon, wie wir an ihn herankommen. Meiner Erfahrung nach reagieren die Schwarmbauten der Silithiden empfindlich auf ihre Umgebung. Das erklärt auch ihre Angriffe, als sie die Todesschreie der Geister hörten.\n\nIm Turm sind die Silithiden am stärksten - dort, wo massenweise Wespen herumschwirren. Besteigt den Turm und scheucht den Schwarmbau auf. Meldet Euch zurück, sobald Ihr etwas erfahren habt, aber seid vorsichtig! Wenn Ihr irgendetwas Hilfreiches entdeckt, bringt es zu mir.", objectives = "Besteigt den Turm beim Südwindposten und findet eine Möglichkeit, den Schwarmbau der Silithiden aufzuscheuchen. Bringt alles Ungewöhnliche, das Ihr dabei entdeckt, zu Layo Starstrike auf den Friedhof Heldenwacht in Silithus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1127] = { title = "Fools Starkbier", description = "Ihr möchtet also etwas von Fools Starkbier, hm? Denkt Ihr daran, wieder die Rennen zu besuchen...?\n\nGut, bringt mir mehr von Zanzils Mixtur und ich braue noch etwas mehr Starkbier für Euch.", objectives = "Bringt 12 von Zanzils Mixturen zu Crank Fizzlebub in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1130] = { title = "Melor schickt Kunde", description = "$N, Melor Stonehoof hat von Euren Taten gehört und Euch einen Weg geebnet.\n\nWenn Ihr ihn einschlagen möchtet, dann geht nach Thunder Bluff und sprecht mit Melor. Ihr findet ihn auf der Anhöhe der Jäger.", objectives = "Sprecht mit Melor Stonehoof in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1131] = { title = "Stahlbiss", description = "Manchmal jagen wir wegen Essen. Manchmal jagen wir wegen der Ehre. Und manchmal jagen wir, um der Lehren der Erdenmutter teilhaftig zu werden.\n\nDoch die Jagd, auf die ich Euch jetzt schicke, hat damit nichts zu tun. Es geht darum, eine Kreatur zu töten, die nicht unter dem Segen der Erdenmutter steht.\n\nDie Hyäne Stahlbiss streift südlich des Brachlandes durch Tausend Nadeln. Sie ist eine Tyrannin, die andere Hyänen anlockt und Furcht und Blutvergießen unter den friedlicheren Wildtieren verbreitet.\n\nSucht Stahlbiss, $n. Sucht und besiegt sie.", objectives = "Bringt Stahlbiss' Rippe zu Melor Stonehoof in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1132] = { title = "Fiora Langohr", description = "Ach, wieder auf See zu sein! Den Kuss des Windes zu spüren und mich von den Wellen wiegen zu lassen wie vor langer Zeit von meiner gesegneten Mutter!\n\nOh, hätte ich doch nur Euer Glück, $C, denn ich sehe das Meer in Eurer Zukunft!\n\nMeine Aufgabe ist es, eifrige Seelen nach Kalimdor zu bringen, in das Land der unbegrenzten Möglichkeiten! Wenn Ihr Euer Glück in Übersee machen wollt, dann reist von hier mit dem Schiff in den wunderschönen Hafen Theramore. Sprecht mit meiner Partnerin, der Elfin Fiora Longears.\n\nSie wird Euer Abenteuer in Kalimdor beginnen lassen!", objectives = "Sprecht mit Fiora Longears in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1133] = { title = "Reise nach Astranaar", description = "Wenn Ihr gerade vom Boot von Menethil kommt, dann solltet Ihr als Erstes nach... Astranaar gehen. Ich bin sicher, ein eifriges Mitglied der Allianz kann dort viel Gutes tun. Sprecht mit Shindrell Swiftfire und bietet Eure Dienste an.\n\nAber erwähnt nicht, wer Euch geschickt hat. Shindrell kennt mich nicht...", objectives = "Sprecht mit Shindrell Swiftfire in Astranaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1134] = { title = "Prachtschwingen des Steinkrallengebirges", description = "Wir führen keinen offenen Krieg mit der Horde, aber der Frieden ist brüchig. Ihre Agenten gehen häufig gegen uns vor, aber stets heimlich.\n\nEiner dieser Feldzüge wurde uns durch geheime Informanten in Theramore enthüllt, die behaupten, dass die Orcs Gift der Prachtschwingen beim Mirkfallonsee im Steinkrallengebirge im Süden sammeln. Dann benutzen Orc-Auftragsmörder das Gift bei ihren geheimen Feldzügen gegen die Allianz!\n\nWenn das stimmt, dann müssen wir sie aufhalten, $N. Wir müssen ihnen den Zugang zu dem Gift versperren.", objectives = "Bringt 12 Prachtschwingengiftbeutel zu Shindrell Swiftfire in Astranaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1135] = { title = "Steilhanggift", description = "Wie Ihr sicher wisst, werden Flügeldrachen oft von Orcs als Reittiere gezähmt. Weniger bekannt indessen ist, dass das Gift eines Flügeldrachen in manchen Kreisen höher geschätzt wird als die Bestie selbst. Falls Ihr also keine Angst vor einer kleinen Flügeldrachenjagd habt... habe ich einen Job für Euch.\n\nEs gibt einen Ort im Land Tausend Nadeln, er liegt westlich von hier, welcher als der Steilhang bekannt ist. Die dort lebenden Steilhangflügeldrachen haben ein starkes Gift. Stark und kostbar.", objectives = "Bringt 10 Steilhanggiftbeutel zu Fiora Longears in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1136] = { title = "Frostrachen", description = "$n, jetzt ist es Zeit, weit entfernte Länder zu bereisen. Ihr seid bereit.\n\nIhr jagt jetzt Frostrachen, einen Yeti im Alteracgebirge. Er ist schwer zu erkennen, da sein weißes Fell mit den Schneefeldern seiner Bergheimat verschmilzt. Man bekommt ihn kaum je zu sehen.\n\nAber ich zeige Euch, wie man eines solchen Geschöpfes habhaft wird. Hier, nehmt diese Rolle. Ich habe darauf vermerkt, wie man Frostrachen anlocken kann.\n\nGeht jetzt, $n. Eure Reise ist lang und viele Herausforderungen harren Eurer. Erst wenn Ihr mit Frostrachens Mähne zurückkehrt, ist Eure Aufgabe abgeschlossen.", objectives = "Bringt Frostrachens Mähne zu Melor Stonehoof in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1137] = { title = "Neuigkeiten für Fizzle", description = "Indurium besitzt einen erstaunlichen Hitzewiderstand! Ich bin sicher, es taugt für Fizzles Kolben. Aber er braucht echtes Indurium, nicht nur die Späne.\n\nDas Erz muss tief in den Minen von Uldaman abgebaut werden, an der Nordgrenze des Ödlandes. Das ist die wahre Quelle von Indurium.\n\nBestellt Fizzle Brassbolts Grüße von mir und sagt ihm, was ich Euch gesagt habe.\n\nAngenehme Reise, $N. Ich wäre nicht überrascht, wenn wir uns wiedersehen - wenn Fizzle von dem Indurium erfährt, schickt er Euch wahrscheinlich nach Uldaman, um es zu holen!", objectives = "Sprecht mit Fizzle Brassbolts in der schimmernden Ebene.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1138] = { title = "Meeresfrüchte", description = "Ich liebe Krebse. Krebse sind die Früchte des Meeres! Man kann sie backen, grillen, kochen und braten. Man kann sie in der Pfanne braten, frittieren und kurzbraten. Es gibt Krebssalat, Krebssuppe, Krebseintopf, Pfefferkrebs, Zitronenkrebs, Peitscherwurzelkrebs und Ironforgekrebs à la Surprise. Das ... das war's eigentlich.\n\nIch angle hier gerade und daher kann ich mir keine feinen Krebsbrocken besorgen. Mann kann sie aus Riffkriechern und verkrusteten Gezeitenkriechern kratzen. Man kann viel mit ihnen anstellen. Man kann sie backen, grillen, kochen ...", objectives = "Sammelt 6 feine Krebsbrocken für Gubber Blump in Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1139] = { title = "Die verlorene Tafel des Willens", description = "Wir haben den Schattenschmiedeklan ausgebremst, indem wir ihn von der Blackrockspitze abgeschnitten haben, doch Hammertoes Mission wurde noch nicht erfüllt. Sein Tod darf nicht umsonst gewesen sein. Er träumte davon, die Schrifttafel des Willens zu finden: eine Steintafel, graviert mit Magie durch die Titanen selbst, die helfen, ihren Schöpfungen Leben einzuhauchen und ihnen damit einen eigenen Willen ermöglichen. So jedenfalls heißt es in den Legenden.\n\nDennoch müssen wir die Tafel bergen, ehe der Schattenschmiedeklan sie finden kann.\n\nKehrt nach Uldaman zurück, sucht die Tafel und kommt unverzüglich wieder her.", objectives = "Sucht die Tafel des Willens und bringt sie zu Berater Belgrum in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1140] = { title = "Der Turm von Althalaxx", description = "Díe Schrift der Orcs ist kaum mehr als das Gekritzel eines Kindes. Viele meines Ordens spotteten, als ich ihre Sprache lernen wollte, aber ich fand es hilfreich, meine Feinde besser zu verstehen.\n\nIlkruds Gekritzel zufolge scheint Athrikus immer noch zwei Seelenedelsteine zu besitzen, und die werden in Nightrun und Satyrnaar aufbewahrt, Satyrgebiete im nordöstlichen Ashenvale.\n\nSeid vorsichtig da draußen, $n, die bluttriefenden Tempel der Satyrn können selbst für abgebrühte $C wie Euch beängstigend sein.", objectives = "Befreit die Hochgeborenenseelen in Night Run und Satyrnaar und kehrt zu Delgren dem Läuterer in Maestras Posten zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1141] = { title = "Die Familie und die Angel", description = "Ich liebe das Angeln. Die Blump-Familie ist berühmt fürs Angeln. Mein Name ist Gubber Blump; ich angle.\n\nEs gibt eine Fischart, die ich hier in der Gegend gern fange. Sie heißt Dunkelküstenbarsch. Früher fuhr ich mit einem Boot hinaus, um Barsche zu angeln, aber seitdem die gemeinen Murlocs gekommen sind, fahren keine Boote mehr raus. Ich wette, dass sie auch alle Barsche aufgefressen haben.\n\nSagt, wollt Ihr mir helfen, Dunkelküstenbarsche zu fangen? Ich würde Euch eine echte Blump-Familienangel geben, wenn Ihr es tun würdet! Es ist eine wirklich gute Angel, um damit Fische zu fangen.", objectives = "Fangt 6 Dunkelküstenbarsche für Gubber Blump in Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1142] = { title = "Die Sterblichkeit schwindet", description = "Ich habe nicht mehr lange zu leben... so... so... schwach.\n\n... der t-t-tapfere Zwerg Lonebrow hat jemanden geschickt, Falfindel zu w-w-warnen...\n\nAber bevor ich... s-s-sterbe...\n\n... meine Frau Treshala... ihr Anhänger des Bundes mit mir... gestohlen... von einem der n-n-niederträchtigen Angreifer...\n\nB-B-Bitte sucht ihn... und bringt ihn Treshala in Darnassus zurück...\n\n... mit der Nachricht meines einsamen... Todes.", objectives = "Sucht und bringt Treshalas Anhänger zu Treshala Fallowbrook in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1143] = { title = "Der Turm von Althalaxx", description = "Verstehe. Also wenn das stimmt, was Ihr sagt, dann ist jetzt die Zeit gekommen, endlich zuzuschlagen. Ich glaube, Athrikus residiert in der Turmspitze. Aber seid vorsichtig, er ist von vielen mächtigen Hexenmeistern umgeben, die tödlicher sind als Eure bisherigen Gegner.", objectives = "Tötet Athrikus Narassin und bringt seinen Kopf zu Balthule Shadowstrike nahe des Turms von Althalaxx.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1144] = { title = "Willix der Importeur", description = "Endlich ist Hilfe eingetroffen!\n\nIhr habt keine Ahnung, wie lang ich hier gefangen gehalten wurde. Ich kann mich nicht erinnern, wann ich zum letzten Mal draußen war.\n\nWisst Ihr, ich bin Unternehmer. Immer am abkupfern, wie man so sagt. Ich habe Wind davon bekommen, dass Mebok Mizzyrix gut für Rotlaubknolle aus diesem Schweinepferch hier bezahlt. Ich dachte mir, das würde ein leichtes Spiel werden. Wie Ihr sehen könnt, habe ich mich geirrt!\n\nWie auch immer, wenn Ihr so freundlich wärt, mir hier raus zu helfen, sollte es Euer Schaden nicht sein.", objectives = "Führt Willix den Importeur aus dem Kral von Razorfen hinaus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1145] = { title = "Der Schwarm wächst", description = "Viele Reisende, die durch Crossroads kamen, halfen mir, Eier vom Feld der Riesen zu sammeln, und viele können Geschichten erzählen, wie tödlich diese Kreaturen sind. Ich habe genug gehört, um diese Insekten als größere Bedrohung einzustufen als meine Meister zuerst dachten.\n\nIch brauche einen Kurier, der nach Orgrimmar reist und sich mit Belgrom Rockmaul trifft. Das dürfte keine Kleinigkeit werden und es sollte nur jemand gehen, der die Aufgabe ernst nimmt.\n\nBelgrom ist für gewöhnlich vor der Halle der Kriegerhelden zu finden.", objectives = "Stellt Korrans versiegelte Notiz Belgrom Rockmaul in Orgrimmar zu.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1146] = { title = "Der Schwarm wächst", description = "Korran ist also zu einer ähnlichen Schlussfolgerung hinsichtlich dieser Insekten gekommen - sie scheinen doch eine größere Bedrohung zu sein, als wir dachten.\n\nVor ein paar Tagen kehrte ein Jäger halbtot aus Tausend Nadeln zurück. Er gehörte zu einem Stoßtrupp, der geschickt wurde, um ein Ausgrabungsteam der Zwerge von der Schimmernden Ebene zu verjagen. Während des Angriffs kamen noch mehr von diesen Insekten aus einer Höhle an der Grabungsstätte und hätten die Gruppe fast getötet.\n\nIhr Anführer war Moktar Krin und sie suchten Zuflucht an der Grenze der Schimmernden Ebene. Bringt ihm diese Notiz.", objectives = "Stellt Belgroms versiegelte Notiz Moktar Krin in Tausend Nadeln zu.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1147] = { title = "Der Schwarm wächst", description = "Hmm. Offenkundig hält Belgrom die Monster für eine Bedrohung. Er möchte sie in die Tiefen zurückgedrängt haben, aus denen sie gekommen sind.\n\nDie Zwerge zu töten, die von der Forscherliga geschickt wurden, genügte wohl nicht - jetzt muss ich eine Gruppe halbtoter Krieger in einen neuen Kampf führen. Aber selbst können wir das nicht; nicht unter diesen Bedingungen. Die Grabungsstätte liegt südlich von hier. Es sollten keine Zwerge mehr in der Gegend sein. Habt Ihr Lust, Klinge oder Stab in die Hand zu nehmen und uns zu unterstützen?", objectives = "Tötet 5 Silithidsucher, 5 Silithidschwarmdrohnen sowie 5 Silithideindringlinge und kehrt zu Moktar Krin in Tausend Nadeln zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1148] = { title = "Teile des Schwarms", description = "Ihr untersucht den Knochenpanzer gründlich. Als Ihr ihn in den Händen dreht, stellt Ihr fest, dass die Chitinplatten derart verflochten sind, dass er dadurch unglaublich hart wird. So etwas habt Ihr noch nie gesehen. Ihr untersucht den Rest des Kadavers und kommt zu dem Schluss, dass diese Kreaturen sehr kräftig und hochentwickelt sind.\n\nAls ihr einen weiteren Blick auf den Knochenpanzer werft, wird Euch klar, dass Korran diese Kreaturen gewiss gern studieren würde. Er könnte dadurch herausfinden, was diese Kreaturen sind und woher sie kommen.", objectives = "Bringt 1 Silithidenherz, 5 Silithidenkrallen und 3 intakte Silithidenknochenpanzer zu Korran in Crossroads.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1149] = { title = "Test des Glaubens", description = "Ihr habt mich also gesucht, oder führt Euch das Schicksal zu mir? Einerlei. Ihr seid jetzt hier, und so wird Eure Reise erneut beginnen.\n\nDas Sein besteht aus vielen Aspekten: Geist, Körper, Verstand. Einige davon kann man anhand der Traditionen einer Kultur bewerten. Von anderen können wir nur hoffen, dass sie in uns selbst existieren. Wenn Ihr einverstanden seid, möchte ich einige der Aspekte in Euch testen.\n\nWenn Ihr besteht, werdet Ihr stärker werden. Wenn Ihr scheitert, werdet Ihr die Weite des Nether begreifen.\n\nAls Erstes ein Test des Glaubens.", objectives = "Wenn Ihr festen Glaubens seid, dann springt von den Planken über Tausend Nadeln.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1150] = { title = "Test der Belastbarkeit", description = "Ich sehe mit Freuden, dass Euer Mut im Lichte Eurer bisherigen Taten unerschütterlich bleibt. Da Euer Glaube stark ist, wird es Zeit, Euren Körper zu testen.\n\nAls Erstes ein Test der Belastbarkeit. Geht mit Freunden zum Bau der Wildfedern westlich vom Freiwindposten. Steigt in die Tiefen ihres Unterschlupfes hinab und zerstört ihre Nahrungsvorräte. Damit solltet Ihr deren Zorn angestachelt haben. Wenn Ihr lange genug überlebt, wird Grenka Blutkreischer Euch persönlich heimsuchen. Tötet sie und bringt mir ihre Klaue, um den Test abzuschließen.", objectives = "Bringt Grenkas Klaue zu Dorn Plainstalker in Tausend Nadeln.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1151] = { title = "Test der Kraft", description = "Zu Zeiten der Alten Götter bewohnten Elementare einen Großteil dieser Welt. Sie beteten die Alten Götter an, und die Götter fesselten die Elementare durch ihre Macht an diese Welt. Als die Alten Götter verbannt wurden, verblassten die Elementare in unserer Welt und kehren jetzt auf Geheiß mächtiger Magier zurück.\n\nAber es gibt Ausnahmen. Einige Elementar waren mächtig genug, aus eigenen Stücken hier zu bleiben. Solch ein Elementar ist Rok'Alim.\n\nSucht Rok'Alim in Tausend Nadeln und tötet ihn, um Eure Kraft zu beweisen.", objectives = "Bringt Fragmente von Rok'Alim zu Dorn Plainstalker in Tausend Nadeln.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1152] = { title = "Test der Lehre", description = "Eure Zeit bei mir neigt sich dem Ende zu. Ich bin wissend, aber den Test der Lehre kann ich Euch nicht stellen. Es gilt, Lektionen zu erlernen und Orte zu besuchen, die in der Zuständigkeit anderer liegen.\n\nWenn Ihr bereit seid, dann sucht Braug Dimspirit auf - er ist ein höchst weiser Schamane. Er wird Euch weiter testen, also achtet auf seine Worte, $N.\n\nWenn Ihr bereit seid, dann sucht den Tunnel, der das Steinkrallengebirge mit Ashenvale verbindet. Dort in der Nähe lebt Braug. Und seid vorsichtig, $N, die Nachtelfen versuchen vielleicht, Euren Test zu behindern.", objectives = "Sucht Braug Dimspirit in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1153] = { title = "Eine neue Erzprobe", description = "$C, Ihr habt mir auch früher schon geholfen. Der Kriegshäuptling ist mit meinen bisherigen Leistungen zufrieden und bittet mich, mit neuer Entschlossenheit fortzufahren. Meine Ehre gebietet, dass ich den Kriegshäuptling wissen lasse, was Ihr alles vollbracht habt, doch zuvor möchte ich Euch abermals um Hilfe bitten.\n\nJüngst kamen Reisende aus dem Süden von einem Ort namens Tausend Nadeln. Dort töteten sie einen Kobold, der eine außergewöhnliche Erzprobe bei sich hatte, wollten sie aber nicht verkaufen. Ich möchte eine Probe dieses Erzes untersuchen.", objectives = "Sucht eine unbearbeitete Erzprobe bei einem Buddler oder Feldmesser der Bruchschnauzen und bringt sie zu Tatternack Steelforge im Camp Taurajo im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1154] = { title = "Test der Lehre", description = "Ihr habt Dorns Tests bestanden und wollt jetzt Eure nächste Prüfung absolvieren. Sehr gut. Bisher sind alle Eure Herausforderungen kindisch gewesen. Es ist leicht, Euren Körper zu testen - bei Eurem Verstand sieht das schon anders aus.\n\nIch werde es mit einfachen Worten erklären: sucht das Buch, das ich Euch nenne, lest es und beantwortet meine Fragen nach seinem Inhalt.\n\nWas für ein Buch, werdet Ihr fragen? Das 'Vermächtnis der Aspekte'. Man findet es in den Tiefen des Dor'danil-Grabhügels im südlichen Ashenvale, wo es von den toten Druiden und deren Tötern bewacht wird.", objectives = "Sucht das 'Vermächtnis der Aspekte' und bringt es zu Braug Dimspirit in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1159] = { title = "Test der Lehre", description = "Gut gemacht, $n. Ihr habt den ersten Teil des Tests der Lehren bestanden, aber es bleibt noch eine Frage zu beantworten. Aber es ist nicht an mir, diese Frage zu stellen.\n\nBesucht Parqual Fintallas in Lordaeron. Er war ein bedeutender Historiker der Menschen, bevor die Seuche ihn erwischte. Jetzt sucht er immer noch Erleuchtung, freilich einer ganz anderen Art.\n\nEr wird eine weitere Forderung an Euch stellen, bevor er Euch etwas fragt, aber Ihr habt Euch bisher meisterhaft geschlagen - ich bin sicher, Ihr werdet dieses Hindernis überwinden.", objectives = "Sucht Parqual Fintallas in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1160] = { title = "Test der Lehre", description = "Ich sage Euch, was Ihr suchen müsst und werde Euch sogar meine Frage stellen, aber nicht, weil Ihr Euch beweisen wollt. Wissen ist weit wichtiger als Kraft. Auch wenn andere Euch in ihren Fähigkeiten überlegen sein mögen, Euer Wissen über die Welt ist wertvoller.\n\nGeht zu dem Kloster im Norden Tirisfals. In der dortigen Bibliothek steht ein Buch mit dem Titel Die Anfänge der Bedrohung durch die Untoten. Es wurde von den jetzt verderbten Paladinen benutzt, um sie in meiner Art des Kampfes auszubilden.\n\nBringt es mir.", objectives = "Sucht Die Anfänge der Bedrohung durch die Untoten und bringt es zu Parqual Fintallas in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1164] = { title = "Von Dieben stehlen", description = "Die Hure! Das Flittchen! Kenata lebt noch; ihre Familie blüht und gedeiht, während ich leide. Verlassene, wahrhaftig!\n\nMeine Familie wurde Opfer der Seuche. Unser Besitz ebenfalls dahin, während des Kriegs geplündert und niedergebrannt. Und nach alledem haben sie und ihre lausigen Kinder die Stirn, das einzig Kostbare zu stehlen, das ich noch hatte.\n\nMir sind die Sachen, die sie gestohlen haben, längst einerlei. Ich möchte ihre Köpfe!\n\nTötet sie für mich! Geht zum Bauernhof der Dabyries in Arathi, nordöstlich der Zuflucht.", objectives = "Bringt Kenata, Fardel und Marcel Dabyries Köpfe zu Genavie Callow in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1166] = { title = "Oberanführer Mok'Morokks Sorgen", description = "Verbeugen Euch vor Oberanführer Mok'Morokk!\n\nRexxar mich machen zu mächtigem Anführer von Stonemaulklan!\n\nIch gut Anführer. Ich Klan sicher machen.\n\nGroße Drachen kommen und machen Feuer in alte Heimat. Ich klug Oger. Finden neu Heimat für Klan hier.\n\nAlte Heimat so schnell verlassen, ich Sachen vergessen. Winzig $R, gehen mein Sachen holen. Gehen nach Süden und suchen mein lecker Grog, mein Schnupftabak und mein Geldkassette. Ich Euch mögen, wenn Ihr das tun. Ihr in Flammenbau und Stonemaul Ruinen schauen... sie dort sein, ich sicher!", objectives = "Oberanführer Mok'Morokk in Brackenwall möchte, dass Ihr seinen Grog, seinen Schnupftabak und seine Geldkassette aus dem Dustwallowsumpf holt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1167] = { title = "Der Turm von Althalaxx", description = "Bevor Ihr Athrikus konfrontiert, wäre es vermutlich klug, Balthule zu konsultieren. Zweifellos ist er wachsam in seinem Wachturm gewesen und könnte Informationen über jüngste Entwicklungen haben.", objectives = "Sprecht mit Balthule Shadowstrike beim Turm von Althalaxx.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1168] = { title = "Armee des schwarzen Großdrachen", description = "Mok'Morokk wurde von Rexxar zum Oberanführer gemacht. Ihm liegt mehr an Macht als an den Ogern.\n\nSchwarze Großdrachen töten viele Oger. Töten Thargs Frau. Mok'Morokk sagt uns, wir müssen fliehen. Lässt uns hierher kommen.\n\nOger sollten kämpfen. Oger nicht gut im Weglaufen. Mok'Morokk schert sich nur um Mok'Morokk.\n\nFür mich Stonemaul Ruinen Heimat. Mir gefallen im Süden. Dieser Ort nicht Heimat.\n\nHelft Ogern, Armee der schwarzen Großdrachen zu bekämpfen. Ich wollen Rache. Ich wollen nach Hause.", objectives = "Tharg in Brackenwall möchte, dass Ihr 15 Späher der Feuermähnen, 10 Aschenschweife der Feuermähnen und 5 Bannschuppen der Feuermähnen tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1169] = { title = "Die Brut identifizieren", description = "Während der törichte Narr Mok'Morokk seine Macht genießt und Tharg mit den Dämonen des Kummers und der Rache ringt und um die Führerschaft des Klans buhlt, scheine ich der Einzige zu sein, der die Ursache der Aggression in unserer alten Heimat herausfinden möchte.\n\nWarum der verwirrte Blick, $n? Erwartet Ihr, dass ich wie ein tumber Grobian spreche, nur weil ich ein Oger bin?\n\nDoch zurück zum Geschäft, bringt mir die Herzen und Zungen der Welpen und Jungtiere. Ich werde die Wurzel dieses Übels finden...", objectives = "Draz'Zilb in Brackenwall hätte gern, dass Ihr ihm 15 sengende Zungen und 15 sengende Herzen bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1170] = { title = "Die Brut von Onyxia", description = "Das Dorf Stonemaul wurde von der Brut von Onyxia überrannt. Aber warum sollte die Tochter des Schwarzen-Großdrache-Lords Deathwing über unser Land herfallen?\n\nDas ist sehr beunruhigend. Gewiss wurde Onyxia aus einem anderen Grund hergeschickt, als eine kleine Schar von Ogern zu belagern.\n\nVerständigt unverzüglich Mok'Morokk! Es muss gehandelt werden.", objectives = "Sprecht mit Oberanführer Mok'Morokk in Brackenwall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1171] = { title = "Die Brut von Onyxia", description = "Ihr lasst mich jetzt in Ruhe. Sagt Draz'Zilb, wir bleiben hier. Keine schwarzen Großdrachen hier.", objectives = "Sprecht mit Draz'Zilb in Brackenwall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1172] = { title = "Die Brut von Onyxia", description = "Onyxias Brut wurde über das Drachendüster verstreut. Es dürfen auf keinen Fall weitere Welpen schlüpfen.\n\nBegebt Euch eilig zum Drachensumpf in den Marschen von Dustwallow. Gewiss hat sie dort einen Hort angelegt. Sucht die Eier der bösen Großdrachen und vernichtet sie.\n\nWir können das Dorf Stonemaul nie zurückerobern, wenn das Umland eine Brutstätte bleibt.\n\nWas Mok'Morokk angeht ... Für den Jammerlappen habe ich andere Pläne.", objectives = "Draz'Zilb in Brackenwall möchte, dass Ihr 5 Eier von Onyxia zerstört.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1173] = { title = "Fordert Oberanführer Mok'Morokk heraus", description = "Ihr wagt es, Oberanführer Mok'Morokk herauszufordern?\n\nHa!\n\nIch zerschmettern einen Winzling von $R!\n\nIhr mir sagen, wenn bereit für ordentliche Tracht Prügel.", objectives = "Besiegt Mok'Morokk und bringt die Nachricht zu Draz'Zilb in Brackenwall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1175] = { title = "Eine Straßenunebenheit", description = "Nach dem schweren Zusammenstoß des Red-Thunder-Rennwagen der Goblins und einem Basilisken hat Kronkrider mich angeheuert, um die Strecke zu warten. Keine Ahnung, was die Tiere in der Ebene fressen, dass sie so groß werden, aber wir müssen sie dezimieren, damit sie nicht auf die Fahrbahn laufen, wenn ein Rennen stattfindet.\n\nIch sag Euch was. Wenn ihr ein wenig Profit machen wollt, zieht los und entfernt die Basilisken aus der Gegend.", objectives = "Tötet 10 Salzsteinbasilisken, 10 Salzsteinkristallhäute und 6 Salzsteinstarrer für Rennsteckenleiter Zherin in der Schimmernden Ebene.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1176] = { title = "Gewicht reduzieren", description = "Wenn es um Rennen geht, zählt jede Kleinigkeit! Ob es sich nun um ein leises Quietschen der Kraftübertragung, eine geringfügige Schwäche der Stoßdämpfer oder ein leichteres Gewicht der Karosserie handelt, man muss alles berücksichtigen.\n\nWir benutzen Geierknochen für kleinere Modifikationen am Chassis unserer Rennwagen, die das perfekte Gleichgewicht zwischen Stärke und Gewicht haben. Und sie sind, was noch besser ist, leicht zu beschaffen, da es in der Salzwüste von Geiern wimmelt.\n\nBringt mir ein paar und ich zahle einen guten Preis dafür.", objectives = "Beschafft 10 hohle Geierknochen für Pozzik in der Schimmernden Ebene.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1177] = { title = "Hunger!", description = "Mud großer Oger.\n\nIch hungrig.\n\nGeht Fische hauen. Bringt Mud Essen.\n\nIhr füttert Mud oder Mud frisst Euch.", objectives = "Mudcrush Durtfeet im nördlichen Dustwallow möchte 12 Schlammflossenköpfe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1178] = { title = "Goblin-Sponsoring", description = "Unser Rennfahrer-Team ist der Stolz aller Goblins. Ihr wärt überrascht, welche Leute unser Team auf die eine oder andere Weise unterstützen.\n\nKennt Ihr Gazlowe? Er treibt auf der ganzen Welt Ersatzteile für uns auf. Er kam sogar mal her, um an einer unserer Aufhängungen zu arbeiten!\n\nVor ein paar Wochen wollte er uns den Prototyp einer neuen Treibstoffeinspritzpumpe schicken, aber sie ist noch nicht eingetroffen. Sonst ist er immer zuverlässig ... Würde es Euch vielleicht etwas ausmachen, nach Ratchet zu gehen und ihn danach zu fragen? Ich will ja nicht drängen, aber die Gnome holen langsam auf!", objectives = "Sprecht mit Gazlowe in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1179] = { title = "Die Brüder Brassbolt", description = "Schon von der Schimmernden Ebene gehört, ja? Das ist eine Salzwüste drüben in Kalimdor, direkt südlich vom Canyon der Tausend Nadeln. Der ideale Austragungsort für Rennen, weil es da so flach ist!\n\nDa draußen sind zwei Gnomenbrüder, Freunde von mir, die ihren neuen Raketenwagen erproben, und soweit ich gehört habe, ist er schnell! Hey, so schnell, dass die Fahrer immer verunglücken. Und Gehirnerschütterungen bekommen.\n\nDarum baten sie mich um ein paar Helme für Belagerungsmaschinen, aber ich kann hier nicht weg, meine Pflicht fesselt mich an diesen Ort. Ich kann die Reise also nicht machen!\n\nKönnt Ihr es?", objectives = "Bringt die Kiste mit Schutzhelmen zu Wizzle Brassbolts in der schimmernden Ebene.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1180] = { title = "Goblin-Sponsoring", description = "Zurück zum Grund Eures Hierseins. Ich weiß, ich habe Pozzik versprochen, dass ich ihm eine neue Treibstoffeinspritzpumpe schicke, aber ich habe sie selbst noch nicht bekommen. Revilgaz drüben in Booty Bay sagte, er würde sie herschicken, aber irgendwie scheint da was schief gelaufen zu sein.\n\nWenn das stimmt, können wir wenig dagegen tun. Aber wir können wenigstens herausfinden, wann sie von Booty Bay abgeschickt wurde.\n\nFragt drüben bei Werftmeister Lozgil nach, er müsste die Frachtbriefe überprüfen können.", objectives = "Sprecht mit Werftmeister Lozgil in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1181] = { title = "Goblin-Sponsoring", description = "Ich fürchte, ich kann Euch nicht weiterhelfen, $n. Wenn Ihr der Sache weiter nachgehen möchtet, würde ich vorschlagen, Ihr geht zum Baron persönlich. Wenn jemand über die Geschäfte von Revilgaz Bescheid weiß, dann Revilgaz selbst.\n\nIhr findet ihn in der Taverne jenseits des Hafens, Obergeschoss.", objectives = "Sprecht mit Baron Revilgaz in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1182] = { title = "Goblin-Sponsoring", description = "Wisst Ihr, die Schredder der Venture Company draußen am Nazferitisee (im Norden des Schlingendorntals) wurden mit einer neuartigen Treibstoffeinspritzpumpe ausgerüstet. Ich dachte mir, Pozzik könnte Kapital daraus schlagen, wenn er einige Einzelheiten erfahren könnte. Leider scheint Cozzle, der dortige Großknecht, etwas schlauer zu sein als ich ihm zugestehen wollte.\n\nAber Ihr seht aus, als könntet Ihr es schaffen, die Blaupausen zu finden. Ich weiß, dass er sie in seinem Haus aufbewahrt, aber mit Sicherheit verschlossen und verriegelt.", objectives = "Bringt die Treibstoffreglerblaupausen zu Baron Revilgaz in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1183] = { title = "Goblin-Sponsoring", description = "Ihr solltet zum Aufbruch bereit sein. Bestellt Pozzik schöne Grüße und sagt ihm, wenn er etwas braucht, soll er keine Hemmungen haben, zu fragen. Ich warte auf die baldige Nachricht, dass er den Streckenrekord gebrochen hat!", objectives = "Bringt die Blaupausen der Treibstoffeinspritzpumpe zu Pozzik in der Schimmernden Ebene.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1184] = { title = "Teile des Schwarms", description = "Geht zurück zu Belgrom in Orgrimmar und sagt ihm, dass Moktar in Tausend Nadeln ganz in seinem Sinne handelt. Sagt ihm auch, dass meine Studien voranschreiten und ich hoffe, dass ich bald mehr gelernt habe. Das sollte ihn freuen.", objectives = "Kehrt zu Belgrom Rockmaul in Orgrimmar zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1185] = { title = "Unter dem Chitin war...", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1186] = { title = "Der achtzehnte Rennfahrer", description = "Ich werde damit beschäftigt sein, diese neue Treibstoffeinspritzpumpe in unsere Rennwagen einzubauen, aber wenn Ihr dem Team noch weiter helfen möchtet, sprecht mit Razzeric. Er ist unser Fahrer - unser achtzehnter Fahrer, um genau zu sein -, und er nimmt selbst gern Veränderungen an den Rennwagen vor.\n\nAber er ist ein wenig daneben, bemüht Euch daher, nicht zu überrascht zu wirken.", objectives = "Sprecht mit Razzeric in der schimmernden Ebene.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1187] = { title = "Razzerics Basteln", description = "Pozzik ist ein toller Mechaniker, das weiß ich, aber er hat Angst davor, einfach was mit viel Power einzubauen und dann loszudüsen. Aber ich nicht.\n\nWenn Pozzik mit einem Rennwagen fertig ist, nehme ich mir die Zeit und baue eigene Veränderungen ein - Ihr wisst schon, die Steuerung lockern, Teile des Rahmens entfernen und ihm mehr Saft geben!\n\nIch habe einen Zephyriumnachbrenner von Shreev im Gizmorium in Gadgetzan bestellt, aber offenbar musste der Zeppelin, mit dem er geschickt wurde, in den Marschen von Dustwallow notlanden! Ich muss das Ding haben, $N!", objectives = "Bergt den Zephyriumnachbrenner für Razzeric in der Schimmernden Ebene.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1188] = { title = "Sicherheit zuerst", description = "Doch wartet, was ist das? Shreev hat die Sicherung aktiviert gelassen. Das reduziert die Menge Energie, die ich aus dem Nachbrenner rausholen kann. Ich sagte ihm, ich wollte sie deaktiviert haben! Das ist nicht gut.\n\nIhr müsst das ins Gadgetzan-Gizmorium in der Tanariswüste bringen und es von Shreev entfernen lassen.", objectives = "Bringt den Zephyriumnachbrenner zu Shreev in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1189] = { title = "Sicherheit zuerst", description = "So, ich habe getan, was Razzeric wollte. Sagt ihm nur, er soll vorsichtig sein, wenn er das zündet. Wenn er den kleinsten Fehler macht, fährt er nicht los, sondern ist nur noch ein Brandfleck auf der Rennstrecke.\n\nWäre doch ein Jammer, wenn das passiert. Wer weiß, ob unser neunzehnter Fahrer genauso gut wäre?", objectives = "Bringt den umgebauten Zephyriumnachbrenner zu Razzeric in der schimmernden Ebene.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1190] = { title = "Tempo halten", description = "Die Brassbolts-Brüder haben einen neuen Baustoff entdeckt, das ist die einzig logische Erklärung. Ihre Rennwagen fahren schneller als vorher, aber Design und alle anderen Daten ihrer Probefahrten sind noch dieselben.\n\nWir wissen, dass Rizzle Brassbolts sich fast ununterbrochen mit den Plänen seiner neuen Entdeckung befasst hat.\n\nZamek kann ein Ablenkungsmanöver inszenieren, damit Ihr diese Pläne von ihnen stehlen könnt.", objectives = "Lasst Zamek ein Ablenkungsmanöver inszenieren und stehlt dann Rizzles Pläne für Pozzik in der schimmernden Ebene.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1191] = { title = "Zameks Ablenkungsmanöver", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1192] = { title = "Induriumerz", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1193] = { title = "Eine beschädigte Falle", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1194] = { title = "Rizzles Baupläne", description = "Rizzles Baupläne beschreiben den Vorgang der Veredelung von Induriumerz. Man kann dem Gekritzel entnehmen, dass Induriumerz an der Ausgrabungsstätte Uldaman der Zwerge im Ödland zu finden ist.\n\nDie anderen Notizen behandeln fast ausschließlich seinen Hitzewiderstand.\n\nAls Briefbeschwerer der Pläne dient ein Klumpen, der wie unbearbeitetes Induriumerz aussieht.", objectives = "Bringt die Induriumerzprobe zu Pozzik in der schimmernden Ebene.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1195] = { title = "Die heilige Flamme", description = "Die Galakzentauren von Tausend Nadeln beschützen ein Artefakt aus der Zeit der Erschaffung der Zentauren.\n\nWir würden es gern bergen, benötigen aber eine Phiole Wasser aus einem der Mondbrunnen der Nachtelfen.\n\nUm dieses Wasser zu beschaffen, müsst Ihr zuerst eine Phiole besorgen, wie sie die Dryaden beim Raynewood im Herzen von Ashenvale besitzen. Am Westufer des Falfarren, südlich der Hauptstraße, befindet sich ein Mondbrunnen, in dem Ihr die Phiole füllen könnt.", objectives = "Bringt eine gefüllte geätzte Phiole zu Zangen Stonehoof in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1196] = { title = "Die heilige Flamme", description = "Bringt die gefüllte Phiole zu Rau Cliffrunner beim Freiwindposten im Südosten von Tausend Nadeln. Ihr gelangt nach Tausend Nadeln, wenn Ihr den großen Aufzug am Südrand des Brachlandes benutzt.\n\nIch wäre nicht überrascht, wenn Ihr uns weiter behilflich sein könntet.", objectives = "Bringt die gefüllte geätzte Phiole zu Rau Cliffrunner im Freiwindposten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1197] = { title = "Die heilige Flamme", description = "Wenn Ihr das Wasser benutzt, das Ihr mitgebracht habt, könnt Ihr vorübergehend die Flamme löschen, die das Zentaurenrelikt schützt. Aber der Effekt ist nicht von Dauer, daher müsst Ihr rasch handeln.\n\nIhr findet die Spalthufklippe, die Festung der Zentauren, nördlich von hier. Die Flamme wird in der Spalthufhöhle bewahrt, einem schwer bewachten Teil der Klippe.\n\nAber seid vorsichtig, die Zentauren der Galak sind dort in großer Zahl zugegen und dürften etwas, das ihnen so teuer ist, nicht freiwillig hergeben.", objectives = "Holt den gespaltenen Huf für Rau Cliffrunner im Freiwindposten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1198] = { title = "Auf der Suche nach Thaelrid", description = "Heutzutage kursieren viele Gerüchte über die Vereinigung der Twilight-Hammer und Naga in der Blackfathom-Tiefe an den Küsten von Ashenvale.\n\nMeine Rolle hier bei der Argentumdämmerung besteht darin, so viele Informationen wie möglich zu sammeln, damit wir wissen, wann und wo Hilfe erforderlich ist.\n\nEs ist jetzt Wochen her, seit ich einen Späher losschickte, um die Aktivitäten in der Blackfathom-Tiefe auszuspähen. Argentumwache Thaelrid hat sich noch nicht zurückgemeldet.\n\nMeine anderen Späher sind mit dringenden Angelegenheiten beschäftigt.\n\nSucht und unterstützt Thaelrid für mich, $N.", objectives = "Sucht Argentumwache Thaelrid in der Blackfathom-Tiefe auf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1199] = { title = "Die Twilight fallen", description = "Mit der Macht der uralten Rituale der chaotischen Alten Götter versuchen die Mitglieder der Twilight-Hammer, ihre dunklen Schutzherren zurückzuholen und Tod und Schrecken in der Welt zu verbreiten.\n\nWir glauben, dass die Twilight-Hammer sich mit den Naga verbündet haben und sich in der Blackfathom-Tiefe an den Küsten von Ashenvale zusammenrotten.\n\nWelch schändliche Pläne in den Tiefen des alten Tempels auch immer geschmiedet werden, wir müssen sie vereiteln.\n\nFührt Krieg gegen die Hammer und bringt Beweise Eurer Taten mit. Eure Bemühungen sollen reich belohnt werden.", objectives = "Bringt 10 Twilight-Anhänger zu Argentumwache Manados in Darnassus", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1200] = { title = "Schurkerei in Blackfathom", description = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'Mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.\n\nDie Kultisten der Twilight-Hammer haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'Mai, um Macht zu erlangen.\n\nBitte, erschlagt Kelris und bringt Selgorm in Darnassus seinen Kopf, $N.", objectives = "Bringt den Kopf des Twilight-Lords Kelris zu Dämmerungsbehüter Selgorm in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1201] = { title = "Theramores Spione", description = "Die Horde und die Allianz wahren einen brüchigen Waffenstillstand. Beide Seiten liefern sich Scharmützel und heimliche Angriffe. Wir müssen dafür sorgen, dass die Horde stets die Oberhand behält!\n\nJetzt haben wir die Chance, genau das zu tun.\n\nSpitzel der Allianz haben Stellungen östlich des Dorfs Brackenwall bezogen. Sie spionieren das Dorf aus und melden unsere Bewegungen Theramore, was wir nicht dulden können.\n\nJagt die Spitzel und schaltet sie aus. Schickt eine deutliche Botschaft an ihre Vorgesetzten, dass wir die Anwesenheit ihrer Spione nicht dulden!", objectives = "Tötet 9 Spitzel von Theramore und kehrt dann zu Nazeer Bloodpike in Brackenwall zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1202] = { title = "Die Docks von Theramore", description = "$n, zwei unserer Spione wurden ausgeschickt, um Dokumente von einem Schiff bei den Docks von Theramore zu stehlen. Sie bekamen die Papiere, wurden aber entdeckt und waren gezwungen, die Dokumente ins Meer zu werfen.\n\nSpäter konnte ein Spion entkommen, die Beute aber nicht bergen. Er informierte mich über sein Scheitern und jetzt gebe ich Euch die Aufgabe.\n\nDie Dokumente sind in einer Schließkiste irgendwo im Wasser unter den Docks von Theramore. Sucht diese Dokumente, $n, und bringt sie mir.", objectives = "Bringt die Dokumente des Kapitäns zu Nazeer Bloodpike in Brackenwall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1203] = { title = "Jarl braucht eine Klinge", description = "Ich habe zu schneiden. Ich kann Euch nicht sagen, was ich schneiden werde, aber... Ich brauche eine Klinge. Eine ganz bestimmte Klinge...\n\nManche Leute sprechen von einem Mondstahlbreitschwert. Ich nenne es eine Schwingklinge.\n\nHelft Ihr mir? Vielleicht findet Ihr sie in der Stadt, vielleicht sprecht Ihr mit einem Schmied und er macht sie eigens.\n\nAber schlaft nicht noch darüber. Was ich schneide, das hält nicht ewig...", objectives = "Bringt ein Mondstahlbreitschwert zu Jarl in den Marschen von Dustwallow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1204] = { title = "Schlammpanzersuppe mit Käfern", description = "Ich arbeite an einem Gericht namens \"Schlammpanzersuppe mit Käfern\". Die wichtigsten Zutaten fehlen mir leider noch immer... aber ich glaube nicht, dass ich einen Fußmarsch durch die Dustwallow-Marschen durchhalten könnte.\n\nNun denn, $N, könntet Ihr für mich auf die Jagd gehen? Als Erstes brauche ich die Zungen von Schlammpanzerschildkröten. Ihr findet die Schlammpanzer entlang der Küste, hauptsächlich im Bereich der Bucht.\n\nAber ich will nicht jede beliebige Zunge! Ich habe gehört, dass die Zungen von einigen Schlammpanzerschildkröten gespalten sind...\n\nMan sagt, diese gespaltenen Zungen hätten einen charakteristischen Geschmack, und den möchte ich in meinem Gericht...", objectives = "Bringt Morgan Stern in Theramore 8 gespaltene Schlammpanzerzungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1205] = { title = "Schlammwühler", description = "Schlammwühler ist ein uralter Krokilisk in den Marschen von Dustwallow. Und seine Zeit zum Sterben ist gekommen.\n\nAlte Knochen knirschen, wenn er seinen gewaltigen Leib durch den Sumpf schleppt, und auch wenn er sich noch mit der Kraft und dem Tempo der Jugend bewegt, martert sein alter Körper den großen innewohnenden Geist, ein Geist, dessen Flamme nicht erlischt.\n\nHeutzutage jedoch leidet er unablässig qualvolle Schmerzen. Ihr müsst das Leben dieser edlen Kreatur beenden, $N. Ihr müsst Schlammwühler Frieden geben.", objectives = "Bringt Schlammwühlers Zahn zu Melor in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1206] = { title = "Jarl braucht Augen", description = "Augensaft ist ein guter Saft zum Trinken. Leider haben die meisten Tierwesen nur zwei Augen.\n\nAber Spinnen haben eine Menge Augen. Jede Menge. Und Graunebelaugensaft ist lecker. Samtig und salzig! Unzerplatzte Spinnenaugen... Ich schmecke sie schon förmlich.\n\nGraunebelspinnen leben westlich von hier in den Graunebelhöhlen. Glaubt Ihr, die Spinnen wurden nach der Höhle benannt... oder ist es umgekehrt?", objectives = "Bringt 40 unzerplatzte Graunebelaugen zu \"Sumpfauge\" Jarl im Swamplight-Anwesen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1218] = { title = "Feine Gewürze", description = "Ich koche gern. Leckere Sumpfküche. Frittierte grüne Froschschenkel und dergleichen.\n\nUnd zum Kochen brauch ich Gewürze. Feine Gewürze. Dann mache ich einen Eintopf und topfe ihn ein und schlabber ihn aus und geb Euch auch was ab.\n\nMögt Ihr Eintopf?", objectives = "Bringt 3 feine Gewürze zu \"Sumpfauge\" Jarl in den Dustwallow-Marschen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1219] = { title = "Der Orc-Bericht", description = "Beim Durchsuchen der lockeren Erde wird die abgetrennte Hand eines Orcs gefunden. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.\n\nDas Pergament ist in der Sprache der Orcs verfasst... und sieht wichtig aus.", objectives = "Bringt den Bericht des Spions zu einem Lieutenant in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1220] = { title = "Captain Mumm", description = "Captain Mumm sollte den Orcbericht sehen, den Ihr gefunden habt, $N. Er kennt die Sprache der Orcs besser als die meisten. Und er sollte wissen, dass sich Spione der Horde bei Theramore aufhalten!\n\nDer Captain befindet sich in der Kaserne auf der nordöstlichen Seite der Insel Theramore.", objectives = "Bringt den Bericht des Spions zu Captain Garran Mumm.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1221] = { title = "Blaulaubknollen", description = "Blaulaubknollen gelten auf der ganzen Welt als Delikatesse! Aber sie sind rar, sehr rar. Man findet sie nur hier im Brachland, tief in der Erde des Krals von Razorfen.\n\nUnd selbst dann sind sie fast nicht zu finden, wenn man nicht weiß, wo man suchen muss! Darum habe ich diese Schnüffelnasenziesel abgerichtet, damit sie sie für mich aufstöbern. Sie haben unheimlich empfindliche Nasen und riechen eine Knolle aus fünfzig Schritt Entfernung.\n\nEs wird nicht einfach sein, aber wenn Ihr mir ein paar Knollen bringt, bezahle ich Euch gut dafür.", objectives = "Schnappt Euch eine Kiste mit Löchern.\nSchnappt Euch einen Schnüffelnasenleitstecken.\nSchnappt Euch das Handbuch für Schnüffelnasenbesitzer und lest es.\n\nBenutzt im Kral von Razorfen die Kiste mit Löchern, um ein Schnüffelnasenziesel zu beschwören, und benutzt den Leitstecken bei dem Ziesel, damit es nach Knollen sucht.\n\nBringt 6 Blaulaubknollen, den Schnüffelnasenleitstecken und die Kiste mit Löchern zu Mebok Mizzyrix in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1222] = { title = "Stinkis Flucht", description = "Klasse, endlich etwas, das mich nicht essen möchte!\n\nIch brauche Hilfe mit den Tierwesen hier, und Ihr kommt gerade recht, $gJungchen:Lady;.\n\nDer Koch Morgan Stern arbeitet an einem neuen Rezept und hat mich hierher geschickt, um Sumpfbohnenblätter zu sammeln. Ich glaube, er findet sie lecker.\n\nWie auch immer, während ich nach einer Sumpfbohnenpflanze suchte ... Wurde ich umzingelt! Könnt Ihr mir hier raus helfen und auf mich aufpassen, während ich nach den Sumpfbohnen suche?", objectives = "Begleitet \"Stinki\" Ignatz und sprecht dann mit Morgan Stern in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1238] = { title = "Der verlorene Bericht", description = "Beim Durchsuchen der lockeren Erde wird die abgetrennte Hand eines Orcs gefunden. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.\n\nDas Pergament ist ein Bericht von einem Orc, der die Stadt Theramore über Wochen ausspionierte.\n\nAls Ihr das Pergament überflogen habt, ist klar, dass es zum Orc-Spionagemeister in Brackenwall gebracht werden muss.", objectives = "Bringt den Bericht des Spions zu Nazeer Bloodpike in Brackenwall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1239] = { title = "Der abgetrennte Kopf", description = "Ausgiebiges Graben fördert den Kopf eines männlichen Orcs zu Tage, der am Hals abgesägt worden war. Seine Lippen sind zu einer höhnischen Grimasse verzerrt, seine dunklen Augen blicken trotzig.", objectives = "Bringt den Kopf des aufsässigen Orcs zu Nazeer Bloodpike in Brackenwall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1240] = { title = "Der Troll-Hexendoktor", description = "Wir müssen die Umstände von Margs Tod erfahren! Und das können wir nur, $N, durch die Hexenmagie der Trolle.\n\nBringt Margs Kopf zu Kin'weelay im Schlingendorntal im Basislager von Grom'gol.\n\nKin'weelay ist der mächtigste Hexendoktor der Darkspeartrolle. Wenn jemand mit Marg Nighteyes Geist sprechen kann, dann er.", objectives = "Bringt den Kopf des aufsässigen Orcs zu Kin'weelay im Schlingendorntal im Basislager von Grom'gol.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1241] = { title = "Der vermisste Diplomat", description = "Kürzlich wurde ein Diplomat nach Theramore geschickt, um sich mit Jaina Proudmoore zu treffen. Dieser Diplomat kam nie an.\n\nIch glaube, die Defias sind in diese Verschwörung verwickelt, weiß aber nicht, wie. Das Verschwinden des Diplomaten wurde noch nicht publik, aber lange kann das nicht mehr so bleiben.\n\nAgenten des Königs durchkämmen die Stadt bereits nach Hinweisen, aber ich habe eigene Verbindungsleute, die ich gern einschalten würde.\n\nIm Tal der Helden lebt ein alter Freund von mir namens Jorgen. Sucht ihn, gebt ihm diese Notiz und folgt seinen Anweisungen.", objectives = "Sucht Jorgen in der Stadt Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1242] = { title = "Der vermisste Diplomat", description = "Bringt diese Notiz zu Elling Trias. Sagt sonst nichts zu ihm. Seid nur höflich und wartet auf seine Antwort. Und keine Bange, er wird antworten.\n\nIch sage Euch das nur noch einmal, $n: nehmt diese Sache ernst und haltet die Klappe.\n\nIhr findet Trias in seinem Käseladen, Trias' Käse, im Handelsdistrikt. Viel Glück.", objectives = "Bringt Jorgens versiegelte Notiz zu Elling Trias in der Stadt Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1243] = { title = "Der vermisste Diplomat", description = "Jorgen, alter Pickel! Aha, so soll es also sein, hm?\n\nNa gut, damit kann ich leben. Ich hoffe, er findet den Wirbelnden Nether umso früher!\n\nSo wird es ablaufen, $n. Ich werde meine Verbindungsleute hier kontaktieren, aber Ihr werdet den Großteil der Beinarbeit erledigen, damit ich ein wenig spare.\n\nGeht nach Dunkelhain im Dämmerwald und sucht Behüter Backus - er patrouilliert meist auf der Nordstraße vor der Stadt. Sagt ihm nur, dass Ihr für mich die Aktivitäten der Defias untersucht, dann wird er Euch mit allen verfügbaren Informationen weiterhelfen.", objectives = "Gebt Behüter Backus im Dämmerwald die versiegelte Notiz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1244] = { title = "Der vermisste Diplomat", description = "Defiasaktivität? Es gibt immer etwas Aktivität; selbst wenn sie unter sich bleiben, betrachten wir sie als Bedrohung.\n\nAber jetzt, wo ich darüber nachdenke, kam es jüngst zu einer seltsamen Beobachtung. Es muss so zwei Wochen her sein, da hatten sich einige ihrer Agenten in Addles Siedlung versammelt. Dem Bericht glaubte ich zu entnehmen, dass etwas Großes vor sich ging.\n\nWarum seht Ihr da nicht zuerst nach und bringt mir alles, was Ihr findet?\n\nDer Bauernhof liegt südlich der Straße von Westfall direkt am Rand des Dämmerwalds.", objectives = "Sucht die Liste der Defias und kehrt zu Behüter Backus im Dämmerwald zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1245] = { title = "Der vermisste Diplomat", description = "Boah, das sieht zu komplex aus, um Euch nur auf eine falsche Fährte zu locken. Ich sollte das nicht einmal ansehen. Sprecht mit Trias - er kann es bestimmt verstehen. Und lasst Euch durch NICHTS aufhalten. Dies ist größer als ich. Vielleicht sogar größer als er, aber wir werden sehen.\n\nUnd tut mir einen Gefallen, $N, sagt keinem, dass ich Euch geholfen habe. Wenn meine Vorgesetzten erfahren, dass ich davon wusste und sie nicht informiert habe, hängen sie mich wahrscheinlich.", objectives = "Bringt die Liste der Defias zu Elling Trias in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1246] = { title = "Der vermisste Diplomat", description = "Ja, jetzt, wo ich darüber nachdenke... Dashel... Dashel irgendwas... Wie war sein Name? FIST! Dashel Stonefist. In manchen Kreisen nennen sie ihn Fist - wahrscheinlich, weil er ein Raufbold ist.\n\nIhr könnt ihn normalerweise in der Altstadt finden - direkt mitten im Zentrum. Redet mit ihm. Wenn es sein muss, dann benutzt ein Schwert oder etwas Schweres und Stumpfes, um ihn zum Reden zu bringen. Und zögert nicht. Wenn er so tief drinsteckt, wie diese Papiere andeuten, wird er Euch freiwillig keine Informationen geben.", objectives = "Sprecht mit Dashel Stonefist in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1247] = { title = "Der vermisste Diplomat", description = "Ja, also... hm... Vielleicht weiß ich was über dieses Treffen in Addles Siedlung. Das war, glaube ich, vor ein paar Wochen. Ich hatte wirklich nichts damit zu tun. Meine Rolle war vorbei, als Plan A schief ging... verdammte Abenteurer.\n\nDer Kerl, den wir für Plan B hatten, kam aus Menethil; ein Typ namens Slim. Mehr weiß ich nicht über ihren Ersatzplan.", objectives = "Sprecht mit Elling Trias in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1248] = { title = "Der vermisste Diplomat", description = "Ein Verbindungsmann von mir verbringt seinen Ruhestand in der Hafenstadt Menethil im Sumpfland. Er sollte Euch auf Euer Wort hin helfen, wenn Ihr ihm sagt, dass Ihr für mich arbeitet. Sein Name ist Mikhail. Bevor er Stormwind vor ein paar Jahren verließ, erwähnte er, dass er Schankkellner werden wollte.\n\nSprecht mit ihm, sucht diesen Slim und findet heraus, ob es noch etwas über diesen entführten Diplomaten zu wissen gibt. Wir müssen herausfinden, wohin sie ihn gebracht haben, oder wenigstens, wer er ist. In der Liste steht nichts von ihren Plänen nach seiner Entführung.", objectives = "Sprecht mit Mikhail im Sumpfland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1249] = { title = "Der vermisste Diplomat", description = "Ihr sagt, Elling hat Euch geschickt? Dann soll Euch meine Gastfreundschaft zehnfach zuteil werden. Wenn Ihr etwas braucht, fragt nur. Ich tue mein Bestes, Euch zu unterstützen.\n\nHmm, Slim sagt Ihr? Bei dem Namen klingelt nichts, aber ich werde nach ihm Ausschau halten.\n\nSchaut jetzt nicht hin, $N, aber der Herr dort am Ausgang sieht herüber. Er folgt unserer Unterhaltung etwas zu intensiv, wenn Ihr versteht, was ich meine. Ich an Eurer Stelle würde tun, was ich kann, um ihn zu schnappen, bevor er zur Tür flieht.", objectives = "Schnappt Tapoke Jahn bevor er entkommt und kehrt dann zu Mikhail in Menethil zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1250] = { title = "Der vermisste Diplomat", description = "Die Defias zahlten mir nicht genug, um für diese Sache zu sterben. Sie entführten den König. Ja, den König von Stormwind, keinen kleinen Diplomaten. Er war auf dem Weg nach Theramore, um sich mit Jaina Proudmoore zu treffen - offenbar eine große Sache und streng geheim. Aber es sind nicht nur die Defias darin verwickelt. Sie arbeiten mit jemandem zusammen. Ich glaube, sie wussten, dass das ihre Kräfte übersteigt.\n\nMeine Aufgabe war es, ihren Mann an Bord des königlichen Schiffes zu bringen, als es im Hafen lag. Der Typ hieß Hendel. Mehr weiß ich nicht. Ich schwöre es!", objectives = "Sprecht mit Mikhail im Sumpfland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1251] = { title = "Der Schwarze Schild", description = "Ein Eisenschild, vom Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus Zur süßen Ruh war.\n\nDer Schild lässt sich von den Mauersteinen des Kamins ablösen.", objectives = "Bringt den geschwärzten Eisenschild zu Krog in Brackenwall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1252] = { title = "Leutnant Paval Reethe", description = "Unter dem Geröll sticht Euch ein Funkeln ins Auge. Kaum sind Schmutz und Asche von dem Objekt gewischt, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.\n\nUnter dem Anker ist der Name \"Lieutenant Paval Reethe\" eingeprägt.", objectives = "Bringt Reethes Abzeichen zu Captain Garran Mumm in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1253] = { title = "Der Schwarze Schild", description = "Ein Eisenschild, vom Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus Zur süßen Ruh war.\n\nDer Schild lässt sich von den Mauersteinen des Kamins ablösen.", objectives = "Bringt den geschwärzten Eisenschild zu Captain Garran Mumm in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1258] = { title = "...und Käfer", description = "Eine weitere Komponente meines neuen Rezepts ist das gepanzerte Bein eines Riesenkrebses. Und die Krebse, die sie in Dustwallow haben - Matschpanzer nennen sie sie -, taugen einfach nichts! Ich fürchte, die einzigen akzeptablen Krebse leben in den Sümpfen des Elends.\n\nDie Schale des Krebsbeins ist das wichtigste Element der Präsentation des Gerichts, daher brauche ich makellose, unverletzte Beine. Ein ausgewachsener Krebs hat möglicherweise nur ein oder zwei Beine, die in Frage kommen, aber ich brauche viel mehr für mein Gericht.\n\nAlso, $N ... seid Ihr bereit für eine Reise?", objectives = "Bringt 12 makellose Kriecherbeine zu Morgan Stern in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1259] = { title = "Leutnant Paval Reethe", description = "Ich kenne den Namen Lieutenant Paval Reethe nicht. Am besten erkundigt Ihr Euch bei Adjudant Tesoran. Er hat alle Aufzeichnungen über die Wachen von Theramore, vom Personal bis hin zur Ausrüstung.\n\nEr sollte Euch nach einem Blick in seine Bücher sagen können, wer dieser Reethe ist.", objectives = "Findet bei Adjudant Tesoran in Theramore mehr über Reethe heraus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1260] = { title = "Morgan Stern", description = "Ich entwickle ein neues Menü für das Restaurant. Es soll aus regionalen Gerichten mit einem Hauch von \"Bayou\" bestehen. Ich glaube, meine Kunden im Blauen Eremiten werden es lieben!\n\nIch schickte meinen Neffen Morgan nach Theramore, einer Stadt am Rand der Dustwallow-Marschen. Er sammelt die Rezepte der Einheimischen und ich muss wissen, was er bisher gefunden hat.\n\nDie Reise nach Theramore ist lang. Zu lang für mich. Aber ich wette, ein $C wie Ihr einer seid, nutzt jede Chance für eine Reise, ja?", objectives = "Sprecht mit Morgan Stern in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1261] = { title = "Marg spricht", description = "Verfluchter Matschpanzer! Man kann Marg nicht töten! Ah, aber ich bin tot. Also muss er mich getötet haben...\n\nAber meine Mission! Meine Mission! Ihr, $n, müsst sie beenden.\n\nIn der Nähe von Theramore sah ich eine Gruppe Soldaten der Allianz am Ufer kampieren. Ein Soldat trug einen Anhänger... einen Anhänger mit mehr Edelsteinen, als ihn sich ein Soldat leisten könnte!\n\nIn jener Nacht schlich ich in ihr Lager und stahl den Anhänger, aber nach meiner Rückkehr zum Stützpunkt tötete mich ein Matschpanzerkrebsmann!\n\n$n, Ihr müsst diesen Matschpanzer finden und den Anhänger retten!", objectives = "Bringt den juwelenbesetzten Anhänger zu Nazeer in Brackenwall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1262] = { title = "Bei Zor melden", description = "Wie seltsam, dass sich der Anhänger, den Marg stahl, in den Händen eines gemeinen Soldaten befand. Vielleicht hatte sich sein Besitzer verkleidet, oder die Soldaten selbst hatten ihn gestohlen!\n\nWas auch immer, dies ist der Anhänger eines Adligen und wir müssen seinen wahren Besitzer finden, wenn wir das Rätsel lösen wollen.\n\nBringt den Anhänger zu Zor Lonetree in Orgrimmar. Er ist mit der Politik der Allianz vertraut und wird wissen, ob dieser Anhänger etwas mit der Geschichte der Adligen von Stormwind zu tun hat.", objectives = "Bringt den Edelstein-Anhänger zu Zor Lonetree in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1264] = { title = "Der vermisste Diplomat", description = "Am Anfang jedes Monats werden die Marines von Kul Tiras bezahlt und verlassen Theramore meist mit anderen Zielen. Viele kommen hierher, um Frauen aufzureißen, zu zechen und ihren Spaß zu haben. Eine dieser Gruppen betrachte ich als Stammgäste der Taverne, und ich glaube, dieser Hendel ist dabei.\n\nKommandant Samaul in Theramore könnte Euch helfen, ihn zu finden, wenn Hendel noch hier stationiert ist. Er ist Proudmoore treu ergeben, aber wenn Ihr Ellings Namen erwähnt, dürfte er Euch helfen... diskret.", objectives = "Sucht Kommandant Samaul in den Marschen von Dustwallow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1265] = { title = "Der vermisste Diplomat", description = "Hendel? Ja, ich kenne den Mann. Aber wozu braucht Ihr einen meiner Soldaten?\n\nHat Elling Euch geschickt, ihn zu finden? Hmm, das gefällt mir ganz und gar nicht. Elling hätte Euch nicht zuerst zu mir geschickt, wenn Euer Anliegen nicht beunruhigend wäre. Ich verstehe, wenn Ihr mir nicht sagen könnt, worum es geht, aber denkt daran: Ich muss dieses Land beschützen. Wenn Ihr vorhabt, die Ruhe zu stören, solltet Ihr mich so viel wie möglich wissen lassen.\n\nIch glaube, Hendel war im ersten Turm außerhalb von Theramore stationiert. Seid vorsichtig.", objectives = "Sucht die Späherwacht nach Spuren des Gefreiten Hendel ab.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1266] = { title = "Der vermisste Diplomat", description = "Der Gefreite Hendel hält sich westlich von hier auf. Im Augenblick ist er auf Wache und beschützt einige von Theramores Spitzeln, während sie ausruhen. Sie behalten Brackenwall, den Stützpunkt der Horde, im Auge und suchen nach allem, das unsere Grenzen bedrohen könnte.\n\nIhr müsstet ihn problemlos finden können; sucht einfach nach Zelten am Straßenrand.\n\nIch muss mich um andere Dinge kümmern, stoße aber bestimmt bald zu Euch. Ihr könnt mich immer im Turm von Lady Proudmoore in Theramore finden, falls Ihr Probleme habt.", objectives = "Sucht den Gefreiten Hendel in den Marschen von Dustwallow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1267] = { title = "Der vermisste Diplomat", description = "", objectives = "Sprecht mit Jaina Proudmore im Dustwallowsumpf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1268] = { title = "Verdächtige Hufabdrücke", description = "Reihen von Hufspuren führen von den noch rauchenden Überresten des Gasthauses Zur süßen Ruh weg. Wenigstens einige Abdrücke sind klar erkennbar, weitere Reihen sind im weichen Schlamm des Sumpfs kaum zu sehen.", objectives = "Berichtet Krog in Brackenwall von den verdächtigen Abdrücken beim Gasthaus Zur süßen Ruh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1269] = { title = "Leutnant Paval Reethe", description = "Unter dem Geröll sticht Euch ein Funkeln ins Auge. Kaum sind Schmutz und Asche von dem Objekt gewischt, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.\n\nUnter dem Anker ist der Name \"Lieutenant Paval Reethe\" eingeprägt.", objectives = "Bringt Reethes Abzeichen zu Krog in Brackenwall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1270] = { title = "Stinkis Flucht", description = "Klasse, endlich etwas, das mich nicht essen will!!!\n\nIch brauche Hilfe mit den Tierwesen hier, und Ihr kommt gerade recht, $gJungchen:Mädel;.\n\nEin Goblin aus Ratchet namens Mebok Mizzyrix braucht ein paar Sumpfbohnenblätter für einen Trank oder so... Mir ist ganz ehrlich einerlei, warum - er hat gut bezahlt und ich kenne diesen Sumpf, also bin ich hier.\n\nZu dumm, dass ich umzingelt wurde, bevor ich die Sumpfbohnen fand! Könnt Ihr mir hier raushelfen und auf mich aufpassen, während ich nach Meboks Pflanze suche?", objectives = "Begleitet \"Stinki\" Ignatz und sprecht dann mit Mebok Mizzyrix in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1271] = { title = "Festmahl im Blauen Eremiten", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1273] = { title = "Befragt Reethe", description = "Es hat lange gedauert, aber ich fand Reethe. Für einen Menschen hatte er sich gut versteckt.\n\nOgron hatte Angst, nach der langen Zeit im Sumpf könnte er verrückt sein. Ihr kommt mit mir, denn wir brauchen Antworten von ihm.", objectives = "Geht mit Ogron und sprecht mit Reethe, dann kehrt zu Krog in Brackenwall zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1274] = { title = "Der vermisste Diplomat", description = "Pardon, $gwerter Herr:holde Dame;. Bischof DeLavey bat mich, Abenteurer zu suchen, die ihm in einer delikaten Angelegenheit helfen könnten.\n\nWenn Ihr so gut sein könntet, heimlich zur Burg Stormwind zu reiten und mit ihm zu sprechen, sobald es Euch genehm ist - er wäre Euch sicherlich für Eure Hilfe dankbar. Und nochmals, bitte seid diskret. Es ist eine wichtige Angelegenheit.", objectives = "Sucht Bischof DeLavey in der Burg Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1275] = { title = "Erforschung der Verderbnis", description = "Törichte Blutelfen spielen mit Dämonenmagie. Wurden sie nicht Zeugen, was mit den Naga und den Satyrn von Kalimdor geschehen ist?\n\nIch fürchte, die Blutelfen werden auf ähnliche Weise deformiert. Azeroth darf kein weiteres Volk abscheulicher Monster hervorbringen.\n\nIch möchte die Hirnstämme der Satyrn und Naga untersuchen, damit ich daraus folgern kann, welches Schicksal die Elfen erwartet. In der Blackfathom-Tiefe, an der Küste von Ashenvale, werdet Ihr sowohl Satyrn als auch Naga finden.\n\nEs ist eine lange Reise, $N.", objectives = "Gershala Nightwhisper in Auberdine möchte 8 verderbte Hirnstämme.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1276] = { title = "Der Schwarze Schild", description = "Ah, jetzt erinnere ich mich! Mosarn ist ein angesehener Schmied in Thunder Bluff. Ich wusste, ich habe den Namen schon einmal gehört.\n\nAls Dank belohnte mich der irdene Ring mit einem von Mosarn hergestellten Satz Rüstungen. Sehr gute Arbeit.\n\nVielleicht kann er Euch mehr über den Schild sagen, den er anfertigte.\n\nEs ist nicht viel, aber da wir aus Reethe nichts Nützliches herausbekamen, haben wir nichts anderes.", objectives = "Bringt den geschwärzten Eisenschild zu Mosarn in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1282] = { title = "Sie nennen ihn den lächelnden Jim", description = "Ich kann nicht anders, der alte Jim da tut mir Leid. Er war nicht immer so. Hatte eine Zeitlang ein Gasthaus im Sumpf, wunderbares Lokal.\n\nHört zu, ich will wirklich nicht darüber sprechen. Besprecht es mit Captain Mumm, wenn es sein muss.", objectives = "Sprecht mit Captain Garran Mumm in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1284] = { title = "Verdächtige Hufabdrücke", description = "Reihen von Hufspuren führen von den noch rauchenden Überresten des Gasthauses Zur süßen Ruh weg. Wenigstens einige Abdrücke sind klar erkennbar, weitere Reihen sind im weichen Schlamm des Sumpfs kaum zu sehen.", objectives = "Berichtet Captain Garran Mumm in Theramore von den verdächtigen Abdrücken beim Gasthaus Zur süßen Ruh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1285] = { title = "Daelins Männer", description = "Reddon... Redpath... Oh, da haben wir ihn! Lieutenant Paval Reethe.\n\nTrat den Wachen von Theramore zusammen mit den meisten Rekruten bei, die mit Lady Proudmoore über das Meer kamen. Meldete sich mit sechzehn Jahren zu den Marines in Kul Tiras. Herausragende Dienste, Beförderungen...\n\nIst als vermisst eingetragen.", objectives = "Kehrt mit den Informationen über Reethe zu Captain Garran Mumm in Theramore zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1286] = { title = "Die Deserteure", description = "Es war ein ständiger Kampf, in den Marschen präsent zu bleiben, aber durch die Kraft unserer Entschlossenheit konnten wir mehrere Wachtürme in diesem Gebiet zur Verteidigung halten.\n\nDie aktuellsten Informationen und Späherberichte, die ich bekam, deuten darauf hin, dass eine Gruppe Deserteure sich in unserem alten Turm bei der verlassenen Wacht, südöstlich des Gasthauses, eingenistet hat.\n\nAnführer der Deserteure ist ein Mann namens Jacken. Seht zu, ob Ihr Informationen über ihn bekommt.\n\nSeid gewarnt, $N. Er könnte sich als harte Nuss erweisen.", objectives = "Sammelt Informationen über Reethe von Balos Jacken und den Deserteuren in den Marschen von Dustwallow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1287] = { title = "Die Deserteure", description = "Reethe? Dieser Feigling?\n\nWir warfen ihn aus dem Lager hinaus, weil er dauernd die Vorräte der Oger in Brackenwall plündern wollte. So viele sind wir nicht, dass wir es mit diesen hirnlosen Schlägern aufnehmen könnten.\n\nEr hat das Fass zum Überlaufen gebracht, daher haben wir ihn sich selbst überlassen.\n\nAlso ich hab Euch geholfen ... Warum helft Ihr jetzt nicht uns und vergesst, dass Ihr uns gefunden habt?", objectives = "Sprecht mit Captain Garran Mumm in Theramore über Reethe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1301] = { title = "James Hyal", description = "Bevor ich hier im Blauen Eremiten arbeitete, wurde ich von einem der besten Küchenchefs und Gastwirte ausgebildet, die ich kenne. Sein Name war James Hyal. Alles, was ich besitze und im Leben erreicht habe, verdanke ich ihm.\n\nIch frage mich, was er wohl so treibt... Sein Bruder Vincent und er wollten in einer Taverne im Hafen von Menethil arbeiten, aber ich habe lange nichts von ihm gehört.\n\nWenn Ihr jemals in diese Gegend kommen solltet, könntet Ihr ihm dann Grüße von mir bestellen?", objectives = "Sprecht mit Vincent Hyal im Hafen von Menethil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1302] = { title = "James Hyal", description = "Mein Bruder James fuhr mit Lady Proudmoore über das Meer. Als Letztes hörte ich, dass die Kämpfe dort drüben beigelegt waren und James irgendwo auf dem Kontinent ein Gasthaus eröffnete. Wo immer er sein mag, ich bin sicher, seine Geschäfte blühen. Er war ein verdammt guter Koch.\n\nAber ich habe eine Weile nichts mehr von ihm gehört - zu sehr mit seinem Gasthaus beschäftigt, denke ich. Der Amtmann in Theramore könnte Euch vielleicht zu ihm führen.", objectives = "Sprecht mit Amtmann Lendry in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1318] = { title = "Die offene Rechnung der Gordok", description = "Nun Ihr de' König sein, vielleicht Ihr kriegen zurück wertvolles Artefakt der Gordok von gruseligen Elf, der sich selbst nennen Prinz! König vor Euch hat versagt, so wie alle Könige seit Tortheldrin - de' gruselige Elf - es gestohlen hat, von damaligen Gordokkönig!\n\nArtefakt heißen Stulpen der Gordokmacht. Alte Zeit Geschichten sagen, nur wahre König de' Gordok kann sie zurückholen. Alte Zeit Geschichten sagen auch, der gruselige Elf ist immer noch hier - Ihr finden es und es werden Eure mächtigen Stulpen, für immer! Yar, ich zeigen!", objectives = "Findet die Stulpen der Gordokmacht und bringt sie zu Hauptmann Krombruch in Düsterbruch.\n\nKrombruch zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1319] = { title = "Der Schwarze Schild", description = "Ich kann Euch leider nicht weiterhelfen, $n, schicke Euch aber zu jemandem, der es kann. Caz Twosprocket, einer unserer besten Schmiede, arbeitet in der Schmiede.\n\nBringt ihm den Schild und hört Euch an, was er zu sagen hat.", objectives = "Zeigt den geschwärzten Eisenschild Caz Twosprocket in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1320] = { title = "Der Schwarze Schild", description = "Ah, das hätte ich fast übersehen... Der Ledergurt an der Rückseite muss verbrannt sein, aber er war offenbar für eine große Person gemacht. Ich schätze, für einen Tauren.\n\nMehr kann ich Euch nicht sagen. Sagt Captain Mumm, es tut mir Leid, dass ich nicht mehr helfen konnte.", objectives = "Sprecht mit Captain Garran Mumm in Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1321] = { title = "Der Schwarze Schild", description = "Hmm... Ich sehe nichts Ungewöhnliches an diesem Schild. Do'gol, der Schmied, sollte ihn sich ansehen. Vielleicht kann er uns mehr sagen, aber große Hoffnungen würde ich mir nicht machen...", objectives = "Zeigt den geschwärzten Eisenschild Do'gol in Brackenwall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1322] = { title = "Der Schwarze Schild", description = "Hmmm, hier am Rand des Schildes steht etwas geschrieben, aber durch die Brandspuren kann man es kaum lesen.\n\nIch brauche Säure, um ihn zu reinigen. Das Gift der Dunkelzahnspinnen im Sumpf würde helfen. Bringt mir ihre Giftsäcke und ich reinige diesen Schild.", objectives = "Bringt 6 säurehaltige Giftbeutel zu Do'gol in Brackenwall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1323] = { title = "Der Schwarze Schild", description = "Oh, ich glaube, ich habe zu viel Säure auf den Schild geschüttet. Lasst mich ein wenig rubbeln...\n\nHm, schwer zu lesen, sieht aber wie der Name Mosarn aus. Nie von ihm gehört. Vielleicht weiß Krog etwas. Krog kennt viele Leute.", objectives = "Sprecht mit Krog in Brackenwall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1324] = { title = "Der vermisste Diplomat", description = "Was?! Ihr kommt hierher und werft mir vor, ich mache mit den Defias gemeinsame Sache und glaubt, ich höre mir diese Beleidigungen an? Etwas sagt mir, dass Ihr das schon lange verdient habt.", objectives = "Besiegt den Gefreiten Hendel in den Marschen von Dustwallow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1338] = { title = "Stormpikes Bestellung", description = "Es gibt einen Rüstungsschmied bei den Zwergen, dessen Arbeit ich sehr bewundere. Sein Name ist Furen Longbeard und seine Fertigkeit unübertroffen. Ich brauche einen neuen Schild und muss einen von ihm haben!\n\nDas Problem ist... Furen lebt weit im Süden im Zwergendistrikt von Stormwind. Im Menschenland! Ich kann mir nicht vorstellen, warum er dort lebt, so weit weg von Ironforge. Die Menschen müssen ihn fürstlich bezahlen, damit er dort bleibt!\n\nWenn Ihr reisen wollt und nichts gegen das Geldverdienen habt, würdet Ihr Furen dann meine Bitte nach einem Schild überbringen?", objectives = "Bringt Stormpikes Bitte zu Furen Longbeard in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1339] = { title = "Gebirgsjäger Stormpikes Aufgabe", description = "Ich hörte, Gebirgsjäger Stormpike sucht nach einem Läufer. Jemand, der eine Reise für ihn unternimmt. Wie wäre es? Seid Ihr ein $R, der für den Job geeignet ist?\n\nWenn ja, findet Ihr Stormpike auf der Spitze des nördlichen Wachturms.", objectives = "Sprecht mit Gebirgsjäger Stormpike.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1358] = { title = "Probe für Helbrim", description = "Ein Kollege in Kalimdor, Apotheker Helbrim, untersucht die Auswirkungen von Lordaerons Toxinen auf die Wildtiere von Kalimdor. Er wäre an einer Probe der Wolfherzen interessiert, die Renferrel mir geschickt hat.\n\nHelbrim lebt im Brachland in einem Dorf, das Crossroads heißt. Um ihn zu erreichen, müsst Ihr per Zeppelin zur Orc-Hauptstadt Orgrimmar reisen und dann zu Fuß Richtung Süden nach Durotar. Geht durch das Brachland nach Westen und Ihr erreicht bald den Ort Crossroads.", objectives = "Bringt die Wolfherzprobe zu Apotheker Helbrim ins Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1359] = { title = "Zinges Lieferung", description = "Die Wolfherzen, die Ihr beschafft habt, verfügen über ein Merkmal, das es in ähnlichen Proben nicht gibt. Sie verfügen über eine Giftigkeit, die für genau die Wölfe tödlich sein müsste, in denen die Herzen schlagen!\n\nEs ist unglaublich und wir müssen das weiter untersuchen. Ich habe einige Proben der gewonnenen Herzen aufbewahrt. Bringt sie zu meiner Kollegin, Apothekerin Zinge. Ihr findet sie in unserem Hauptquartier in Undercity.", objectives = "Bringt die Wolfherzproben zu Apothekerin Zinge nach Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1360] = { title = "Wiederbeschaffte Schätze", description = "Ich hatte selbst eine gute Arbeitsstelle als Buddler an der Uldaman-Ausgrabungsstätte im Ödland... das heißt, bis diese verfluchten Troggs auftauchten. Ich konnte gerade noch mit heiler Haut entkommen, das war alles. In dem Chaos habe ich meinen wertvollsten Besitz zurückgelassen. Natürlich ist er in meiner Truhe sicher vor den Troggs, aber die befindet sich mitten unter ihnen.\n\nIch wäre in Eurer Schuld, sowohl in Ehre als auch in Münze, wenn Ihr sie für mich besorgen könntet! Eine Truhe mit meinem Namen darauf befindet sich am Ende der Nördlichen Bankenhalle. Dorthin müsst Ihr gelangen.", objectives = "Holt Krom Stoutarms wertvollen Besitz aus seiner Truhe in der nördlichen Bankenhalle von Uldaman und bringt den Schatz zu ihm nach Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1361] = { title = "Regthar Totenfurt", description = "Ein Krieger der Horde, Regthar Deathgate, rekrutiert Agenten für einen Einsatz im Land Desolace. Sprecht mit ihm, wenn Ihr Euch freiwillig melden wollt. Er lebt im Brachland in einer Reihe von Bunkern westlich von Crossroads.\n\nUnd schärft Eure Waffen. Desolace ist ein vom Krieg zerrissener Ort.", objectives = "Sprecht mit Regthar Deathgate.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1362] = { title = "Die Kolkar von Desolace", description = "Die Kolkarzentauren leben in Desolace. Ihre Truppen sind in das Brachland vorgestoßen. Das ist bekannt. Agenten der Horde kümmern sich dort um sie.\n\nAber so lange die Zentauren in Desolace so stark sind, werden sie immer eine Bedrohung sein. Mit der Zeit schaffen wir uns diese Bedrohung vom Hals.\n\nSprecht mit Felgur Twocuts beim Geistwandlerposten in Desolace. Seine Aufgabe war es, Informationen über die Zentauren zu sammeln. Er weiß bestimmt, wie man am besten mit den Kolkar von Desolace fertig wird.", objectives = "Sprecht mit Felgur Twocuts beim Geistwandlerposten in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1363] = { title = "Mazens Befehl", description = "Als Verwalter der Arbeit hier in der Bibliothek der Akademie der Arkanen Künste und Wissenschaften liegt es in meiner Verantwortung, dafür zu sorgen, dass alle magischen Folianten und Rollen stets erfasst sind. Wer weiß, was Schlimmes geschehen würde, fielen einige dieser verzauberten Texte in die falschen Hände?\n\nDabei fällt mir ein ... mein Assistent Dellis machte letzte Woche einen schrecklichen Fehler. In der Bibliothek ist er recht tüchtig, aber inkompetent, wenn er die Tore von Stormwind hinter sich lässt. Seid ein Held und helft dem alten Dellis, ja?", objectives = "Sprecht mit Akolyt Dellis in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1364] = { title = "Mazens Befehl", description = "Meister Mazens Anweisungen waren ganz klar: Bringt einen sehr wichtigen Essay zu Behüter Mahar Ba in der Burg Nethergarde.\n\nAber ich bin noch nie in den Verwüsteten Landen gewesen. Die Reise war beängstigend!\n\nAls ich an die Sümpfe des Elends kam, bog ich falsch ab und war plötzlich von grässlichen pflanzenartigen Sumpfwesen umzingelt. Sie schienen mich angreifen zu wollen, also lief ich weg. Doch in meiner Hast ließ ich den Essay fallen. Ich bin sicher, eine der Bestien hat ihn genommen.\n\nKönntet Ihr bitte versuchen, ihn zu holen und zu Mahar Ba zu bringen?", objectives = "Rettet Khadgars 'Abhandlungen über dimensionale Konvergenz' und bringt sie zu Behüter Mahar Ba in der Burg Nethergarde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1365] = { title = "Khan Dez'hepah", description = "Die Kolkar sind nicht die einzigen Zentauren von Desolace. Viele Klans ziehen durch diese trockenen Ebenen, bekämpfen einander und sterben. Und es ist gut, dass sie sich untereinander bekämpfen, denn sie sind stark und brutal. Vereinten sich die Zentauren gegen uns, wären sie ein schrecklicher Gegner.\n\nWir müssen sie erledigen, bevor sie sich zusammentun.\n\nEuer erster Schritt ist, den Kolkarklan zu schwächen. Macht das, indem Ihr den Anführer Khan Dez'hepah besiegt.\n\nDas Dorf Kolkar liegt nordöstlich von hier. Geht, und möge Euch das Glück hold sein.", objectives = "Bringt Khan Dez'hepahs Kopf zu Felgur Twocuts in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1366] = { title = "Zentaurenkopfgeld", description = "Da Ihr die Zentaurenklans jetzt eingeschüchtert habt, wird es Zeit, sie bluten zu lassen. Wenn Ihr durch Desolace reist, jagt Zentauren. Mir ist gleich, welchen Klan Ihr jagt. Sammelt nur Ohren. Bergeweise Ohren.\n\nWenn Ihr ihre Zahl dezimiert, schwächt Ihr ihre Entschlossenheit und macht alle Gedanken an Expansion zunichte.\n\nGute Jagd, $n.", objectives = "Bringt 15 Zentaurenohren zu Felgur Twocuts in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1367] = { title = "Allianz mit den Magram", description = "Um die Zentauren zu schlagen, müssen wir ihren Hass gegen sie wenden. Wir verbünden uns mit einem Klan und lernen durch ihn, wie wir alle Klans besiegen können.\n\nWenn Ihr Euch mit den Magram verbünden wollt, dann tötet ihre Gegner, die Gelkis. Das wird Euch den Respekt der Magram einbringen. Wenn Ihr genug verdient habt, dann trefft Euch mit dem Sprecher der Magram Warug am Rand des Dorfes Magram im Südosten von Desolace.", objectives = "Baut Euch einen freundlichen Ruf bei den Magram auf und sprecht dann mit Warug.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1368] = { title = "Allianz mit den Gelkis", description = "Um die Zentauren zu schlagen, müssen wir ihren Hass gegen sie wenden. Wir verbünden uns mit einem Klan und lernen durch ihn, wie wir alle Klans besiegen können.\n\nWenn Ihr Euch mit den Gelkis verbünden wollt, dann tötet ihre Gegner, die Magram. Wenn Ihr Euch den Respekt der Gelkis verdient habt, dann trefft Euch mit der Schamanin der Gelkis Uthek der Weisen am Rand des Dorfes Gelkis im Südwesten von Desolace.", objectives = "Baut Euch einen Ruf als freundliche Person bei den Gelkis auf und sprecht dann mit Uthek der Weisen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1369] = { title = "Zerbrochene Tränen", description = "Die Gelkis glauben, dass unsere Zentaurenmutter Theradras uns beschützt. Sie sind dumm. Niemand beschützt die Zentauren. Die Magram brauchen keinen Schutz! Wir sind die Stärksten!\n\nZeigt den Gelkis, dass sie dumm sind. Geht zu der Höhle in ihrem Dorf. Sie horten Kristalle in dieser Höhle, die Tränen von Theradras. Zerstört die Tränen und bringt mir die zerbrochenen Stücke!", objectives = "Wahrt Euren Ruf bei den Magram und bringt 3 zerbrochene Tränen zu Warug im Dorf Magram.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1370] = { title = "Diebstahl von Vorräten", description = "Wenn wir nicht im Krieg sind, jagen wir wegen Fleisch. Fleisch gibt uns Kraft und volle Bäuche kämpfen besser als leere.\n\nSo ist es bei den Magram. Sie lagern extra Fleisch ein, damit sie zwischen den Jagdausflügen länger kämpfen können. Wenn man ihr Dorf im Osten überfällt und ihre Fleischvorräte raubt, wird ihre Kraft schwinden.", objectives = "Bringt 6 Taschen primitiv getrocknetes Fleisch zu Uthek der Weisen im Dorf Gelkis.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1371] = { title = "Gizmo für Warug", description = "Vor langer Zeit kam ein kleiner Gnom nach Desolace. Er hatte Pferde und einen Karren, und auf dem Karren viele seltsame Dinge. Komische Dinge. Dinge, die in verschiedenen Farben brannten. Dinge, die sich bewegten und doch nicht lebten. Ich tötete den kleinen Gnom, aber vorher ... brachte er mich zum Lachen.\n\nIch behielt mein liebstes Ding von dem Wagen. Es war ein Mensch aus Holz, der mir zuwinkte, bis ich ihn schlug und zerbrach.\n\nIch will einen Neuen. Besorgt mir einen Neuen!", objectives = "Wahrt Euren Ruf bei den Magram und bringt eine hochentwickelte Zielattrappe zu Warug im Dorf Magram in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1372] = { title = "Nichts als die Wahrheit", description = "Auf Befehl von Varimathras wurde unsere Expeditionsstreitmacht ausgeschickt, um das untere Azeroth zu vermessen.\n\nBeim Spähen bemerkte ich einen Spitzel der Menschen, der den Bettlerschlupfwinkel ausspionierte. Ehe ich ihn festnehmen konnte, schnappten ihn einige unserer ... Orcbrüder ... und brachten ihn nach Stonard, ihrer Festung in den Sümpfen des Elends.\n\nIch möchte unseren Orcverbündeten ... helfen. Sie sahen unser Lager hier nicht, dennoch wollte ich sie unterstützen.\n\nIch arbeitete hier mit Faustin, um ein ... Wahrheitsserum für unseren Freund in Stonard zu entwickeln.", objectives = "Sprecht mit Apotheker Faustin im Bettlerschlupfwinkel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1373] = { title = "Ongeku", description = "Ihr müsst noch mehr beweisen und Eure nächste Aufgabe führt Euch weit weg, daher werden die Gelkis die Magram vorerst ohne Euch bekämpfen.\n\nDie Erde flüstert jenen, die zuhören, viele Geheimnisse zu. Ein Geheimnis, von dem ich höre, betrifft einen roten Kristall. Er heißt Draenethyst und ist neu auf unserer Erde. Er stammt von einem Ort, wo Berge fliegen und Dämonen herrschen.\n\nBringt mir einen Splitter Draenethyst; er macht meine Magie stark! Der Splitter befindet sich an einem Ort namens Sümpfe des Elends und ist im Besitz von Ongeku, dem Verirrten.", objectives = "Wahrt Euren Ruf bei den Gelkis und bringt einen Draenethystsplitter zu Uthek der Weisen im Dorf Gelkis in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1374] = { title = "Khan Jehn", description = "Die Erde spricht zu mir und sagt, dass die Magram schwach werden. Jetzt ist es Zeit, ihren Khan zu töten!\n\nBringt mir den Kopf des Magramkahns Jehn!", objectives = "Bringt Khan Jehns Kopf zu Uthek der Weisen im Dorf Gelkis in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1375] = { title = "Khan Shaka", description = "Ihr helft den Magram und ich mag Euch. Tötet jetzt den Khan der Gelkis! Er ist Khan Shaka und ich will seinen Kopf! Ich möchte seinen Kopf ansehen und ihn auslachen!", objectives = "Wahrt Euren Ruf bei den Magram und bringt den Kopf von Khan Shaka zu Warug im Dorf Magram in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1380] = { title = "Khan Hratha", description = "$N, Ihr habt uns gegen die Magram geholfen. Jetzt helft uns dabei, die Maraudine zu schlagen! Tötet den Anführer ihres Klans, Khan Hratha!\n\nUm ihn herauszufordern, blast das Kriegshorn der Maraudine. Es befindet sich auf einem hohen Steilhang im Tal der Speere.\n\nDoch um das Horn zu blasen, müsst Ihr erst ein Kriegshornmundstück erwerben. Diese Teile sind selten und sind ausschließlich im Besitz der vertrauenswürdigsten Maraudinezentauren.\n\nNachdem das Horn geblasen wurde, werden Zentauren kommen. Tötet sie, bis Hratha auftaucht.\n\nKhan Hratha besitzt ein Stück eines... Schlüssels. Bringt es mir...", objectives = "Wahrt Euren Ruf bei den Gelkis und bringt das Schlüsselfragment der Maraudine zu Uthek der Weisen im Dorf Gelkis.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1381] = { title = "Khan Hratha", description = "Der Khan der Gelkis ist tot, und jetzt werden die Maraudine fallen! Tötet Hratha, den Khan der Maraudine!\n\nUm ihn herauszufordern, blast das Horn auf dem hohen Steilhang im Tal der Speere. Doch um das Horn zu blasen, braucht Ihr erst ein Kriegshornmundstück. Um ein Mundstück zu erwerben, müsst Ihr Zentauren der Maraudine töten. Tötet sie so lange, bis Ihr ein Mundstück findet. Dann blast das Horn.\n\nTut dies, und Zentauren der Maraudine werden zum Turm kommen. Tötet sie, bis Khan Hratha auftaucht. Khan Hratha besitzt ein Stück eines Schlüssels. Gebt mir dieses Stück...", objectives = "Wahrt Euren Ruf bei den Magram und bringt das Schlüsselfragment der Maraudine zu Warug im Dorf Magram in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1382] = { title = "Seltsame Allianz", description = "Wir können von Glück reden, dass die Zentauren sich untereinander bekämpfen, denn als vereinigte Kraft könnte sie nichts aufhalten. Ja, das kommt uns zu Gute und wir sollten unseren Vorteil ausbauen.\n\nEiner der Zentaurenklans, der Gelkisklan, führt einen brutalen Krieg gegen den Magramklan. Wenn wir die Magram angreifen, können wir vielleicht eine Allianz mit den Gelkis schmieden.\n\nSprecht mit Uthek der Weisen im Randbezirk der Gelkislager im Südwesten von Desolace. Durch sie könnten wir eine Allianz mit den Gelkis schmieden.", objectives = "Baut eine freundliche Beziehung zu den Gelkis auf und sprecht dann mit Uthek der Weisen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1383] = { title = "Nichts als die Wahrheit", description = "Mir schwebt genau das richtige Serum vor. Es wird die Wahrheit genau so behandeln, wie die Wahrheit behandelt werden sollte.\n\nFür dieses Gebräu brauche ich mehrere Schattenpantherherzen aus dem Sumpf. Außerdem brauche ich den verzauberten Fungus des Morastlords, der dort haust. Ich bin sicher, jemand, der so tüchtig ist wie Ihr, $n, kann ihn überreden, sich von einigen zu trennen.\n\nDie schwierigste Aufgabe wird sein, einen Tiefschreitertumor aus dem fernen Desolace zu beschaffen. Nur sehr selten werden die Riesen dort krank, sodass ein Tumor entsteht.\n\nUnd jetzt fort mit Euch!", objectives = "Apotheker Faustin im Bettlerschlupfwinkel braucht 5 Schattenpantherherzen, Morastlordfungus und einen Tiefschreitertumor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1384] = { title = "Überfall auf die Kolkar", description = "Die Kolkarzentauren glauben, ihre Magie sei stark. Die wissen nicht, was Magie ist! Nie und nimmer würden die richtige Magie überhaupt erkennen!\n\nIhr werdet ihnen zeigen, dass ihre Magie schwach ist. Geht zu den Kolkar im Nordosten und tötet sie. Nehmt ihre Glücksbringer. Bringt mir die Glücksbringer und ich werfe sie ins Feuer und lache!", objectives = "Wahrt Euren Ruf bei den Gelkis und bringt 10 kunstlose Glücksbringer zu Uthek der Weisen im Dorf Gelkis in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1385] = { title = "Brutale Politik", description = "Desolace ist ein Land im Krieg. Die Zentauren führen Krieg untereinander und wir glauben, der Sieger wird marschieren und unsere Festungen bedrohen. Das können wir nicht dulden.\n\nWir müssen lernen, wie man die Zentauren schlägt, und dazu... müssen wir uns mit einem der Klans verbünden. Die Zentauren der Magram führen Krieg mit den Gelkis. Wenn Ihr gegen die Gelkis kämpft, dann erwägen die Magram vielleicht eine Allianz.\n\nErringt die Gunst der Magram und sprecht dann mit Warug im Dorf Magram im Südosten von Desolace.", objectives = "Baut Euch einen freundlichen Ruf bei den Magram auf und sprecht dann mit Warug.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1386] = { title = "Angriff auf die Kolkar", description = "Die Kolkar halten sich für stark, aber wir lachen über sie! Wir lachen und wir töten sie! Tötet auch Ihr sie. Zeigt mir, dass Ihr Kolkar genauso wie wir töten könnt. Geht nach Norden und tötet sie alle!", objectives = "Haltet Euren Ruf bei den Magram aufrecht. Tötet 12 Zentauren der Kolkar, 12 Späher der Kolkar sowie 6 Raufer der Kolkar und kehrt dann zu Warug ins Magramdorf in Desolace zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1387] = { title = "Zentaurenkopfgeld", description = "Viele Klans bilden das Volk der Zentauren. Jeder hat seinen Anführer und eine Agenda, aber alle Klans haben eines gemeinsam: Grausamkeit.\n\nWenn wir je Frieden finden wollen, müssen die Zentauren entfernt werden. Und ich übertrage Euch die Aufgabe, genau das zu tun.\n\nWenn Ihr durch Desolace zieht, jagt Zentauren und sammelt ihre Ohren. Bringt mir viele, viele Ohren.\n\nMacht das im Dienst der Allianz, $n, und wir sind dem Ende des Krieges einen Schritt näher.", objectives = "Bringt 15 Zentaurenohren zu Corporal Melkins bei der Nijelspitze in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1388] = { title = "Nichts als die Wahrheit", description = "Alles läuft genau nach Plan, $n. Ich möchte, dass Ihr dieses Wahrheitsserum dem Todespirscher Zraedus gebt. Er wird Euch zeigen, wie man es richtig... anwendet.\n\nHa-ha!", objectives = "Gebt Faustins Wahrheitsserum dem Todespirscher Zraedus im Bettlerschlupfwinkel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1389] = { title = "Draenethystkristalle", description = "Die Verirrten, die im Fallow Heiligtum leben, sehen aus wie wir, aber sie sind Monster... die üblen Unbilden auf unserem Trek nach Azeroth haben sie wahnsinnig gemacht. Einst waren sie unsere Brüder, doch nun leben sie im Fallow Heiligtum im Osten und fangen oder töten alle, die sich in die Nähe wagen.\n\nUnd sie haben uns etwas Heiliges gestohlen - Draenethystkristalle.\n\nUns fehlt die Kraft, das Fallow Heiligtum zu betreten und unseren gestohlenen Draenethyst von ihren Hütten und Lagerfeuern zu holen, aber ohne diese Kristalle... könnten auch wir vom rechten Weg abkommen.", objectives = "Bringt 6 Draenethystkristalle zu Magtoor im Sicheren Hafen in den Sümpfen des Elends.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1391] = { title = "Nichts als die Wahrheit", description = "Wir müssen mit einer gewissen Diskretion vorgehen. Immerhin werdet Ihr nicht da reinspazieren und den Narren überzeugen, Faustins Gebräu zu trinken, richtig?\n\nAber wenn es eines gibt, zu dem die Menschen nicht nein sagen können, dann ist es Fusel. Ich nehme Faustins Serum und mische es in dieses Bier. Der arme Kerl wird garantiert keine Hemmungen haben, wenn es darum geht, ein Gebräu zu kippen.\n\nGeht hastig nach Stonard in den Sümpfen des Elends, $n. Und schweigt schön stille über unsere kleine Mission ...", objectives = "Bringt Zraedus' Bräu zu Spitzel Marksen in Stonard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1392] = { title = "Noboru der Knüppel", description = "Noboru verseuchte die Draenei des sicheren Hafens seit Monaten; sein Knüppel ist ein Symbol der Brutalität, die sie sich von den Verirrten gefallen lassen mussten.", objectives = "Bringt Noborus Knüppel zum Anführer des Sicheren Hafens in den Sümpfen des Elends.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1393] = { title = "Galens Flucht", description = "Bitte helft! Diese Kreaturen werden mich fressen!\n\nHelft mir hier raus und ich gebe Euch einen großen Schatz! Er ist in meinem Lager im Sumpf im Norden von Stonard, aber in einer Geldkassette eingeschlossen, die man mit einem Trick öffnet, den nur ich beherrsche.\n\nWenn ihr mir zur Flucht verhelft, zeige ich ihn Euch.", objectives = "Eskortiert Galen, bis er außer Gefahr ist, sucht dann sein Lager in den Sümpfen des Elends und öffnet seine Geldkassette.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1394] = { title = "Letzte Überfahrt", description = "Ihr habt Eure Sache gut gemacht, $n. Ihr habt meinen Test und die Tests vor meinem bestanden. Kehrt zu Dorn in Tausend Nadeln zurück. Er wird die Veränderung in Euch spüren und sehen, dass Euer Verstand, Körper und Geist stark genug sind, dass Ihr für Eure Bemühungen belohnt werden solltet.\n\nBleibt dem Gleichgewicht treu, das Ihr während all dieser Prüfungen gezeigt habt, $n. Wenn Ihr das tut, wird Dorn Euch irgendwann noch einmal prüfen.", objectives = "Sprecht mit Dorn Plainstalker in Tausend Nadeln.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1395] = { title = "Vorräte für Nethergarde", description = "Diese Kiste mit Kraftsteinen muss in die Burg Nethergarde in den Verwüsteten Landen. Sie werden ihre Macht nicht lange halten, daher können wir sie nicht mit der nächsten Karawane aufgeben.\n\nIhr müsst sie nehmen, und zwar schnell.\n\nBringt sie zu Rüstmeister Lungertz in der Burg Nethergarde. Um die Burg zu erreichen, müsst Ihr nach Osten über den Gebirgspass der Totenwinde, dann nach Osten durch die Sümpfe des Elends und dann nach Süden durch die Verwüsteten Lande.\n\nSeid vorsichtig, $n. Ihr müsst durch gefährliche Länder und dürft doch nicht verzagen.", objectives = "Bringt die Kiste mit den Kraftsteinen zu Rüstmeister Lungertz, bevor die Kraft verbraucht ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1396] = { title = "Lauernde Tierwelt", description = "Meine Karawane sollte zur östlichen Küste ziehen, aber wir erreichten unser Ziel nicht. Verirrte haben uns angegriffen, die Wachen getötet und die Vorräte verstreut.\n\nIch allein habe ihren Angriff überlebt. Ich habe geschworen, die verbliebenen Vorräte zu schützen, aber wilde Kreaturen schleichen in der Nähe herum. Bitte helft mir, mein Lager gegen diese Bestien zu verteidigen!", objectives = "Tötet 8 junge Sägezahnkrokilisken, 10 Trauerspinner sowie 10 Sumpfjaguare und kehrt dann zu Behüter Biggs in den Sümpfen des Elends zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1398] = { title = "Treibholz", description = "Ich stehe tief in Eurer Schuld, $N. Ein ehrenhaftes Herz schlägt in Eurer Brust. Und jetzt habe ich eine andere Aufgabe, für die ich demütig um Eure Mithilfe bitte.\n\nWenn ich Nethergarde erreichen soll, dann muss ich diesen Wagen reparieren. Und dafür ... brauche ich Holz. Starkes, trockenes Holz - nicht das schimmelige, krumme Holz der Sumpfbäume.\n\n$N, geht nach Osten zur Küste und sucht nach in der Sonne getrocknetem Treibholz. Bringt es mir.", objectives = "Bringt 8 Stücke sonnengetrocknetes Treibholz zu Behüter Biggs in den Sümpfen des Elends.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1418] = { title = "Neeka Blutnarbe", description = "Das Ödland ist unwirtlich und liegt nahe am Land des Loch Modan, das von der Allianz beherrscht wird, daher wird die Kommunikation zwischen Stonard und den Ödland-Außenposten von Kargath oft unterbrochen.\n\nBeweist Euch, $N. Reist ins Ödland und sprecht mit Neeka Bloodscar, der obersten Späherin des Kargath-Außenpostens. Sprecht mit ihr und bringt mir ihren Bericht.", objectives = "Sprecht mit Neeka Bloodscar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1419] = { title = "Kojoten-Diebe", description = "Habt Ihr viele Tage im Ödland verbracht, $C? Habt Ihr sein Herz gespürt? Habt Ihr den Bestien getrotzt, die durch die staubigen Ebenen schleichen? Dann wird es aber höchste Zeit.\n\nKlippenkojoten sind zähe Burschen. Zäh und tollkühn genug, dass sie sich nach Kargath schleichen und unsere Essensvorräte stehlen. Helft mit, den Außenposten von diesen Dieben zu befreien!\n\nJagt Klippenkojoten, $n. Jagt sie und bringt mir ihre Kieferknochen. Bringt mir genügend und ich glaube Euch vielleicht, wenn Ihr sagt, dass Ihr das Ödland kennt.", objectives = "Bringt 30 Kojotenkieferknochen zu Neeka Bloodscar in Kargath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1420] = { title = "Bericht für Helgrum", description = "Ich schrieb einen neuen Bericht für Helgrum in Stonard. Bringt ihn zu ihm.\n\nUnd wenn Ihr Euch als Kundschafter betrachtet, kommt nicht vom Weg ab. Oder fallt einem Feind in die Hände.", objectives = "Bringt Neekas Bericht zu Helgrum dem Hurtigen in Stonard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1421] = { title = "Die verlorene Karawane", description = "Ich wurde während des Angriffs der Verirrten betäubt, aber bevor mir schwarz vor Augen wurde, sah ich einen unserer Wagen, der zum Fallow Heiligtum gezerrt wurde, zum Dorf der Verirrten im Norden.\n\nEine Karawanentruhe mit wertvollen Reagenzien war in diesem Wagen, Reagenzien, die unabdingbar für die Studien der Hexer der Burg Nethergarde sind. Sucht die Truhe und holt diese Reagenzien, $N. Holt sie und bringt sie mir.", objectives = "Sucht die Karawanentruhe im Fallow Heiligtum, beschafft Euch die Reagenzien der Hexer und bringt sie zu Behüter Biggs.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1422] = { title = "Gefahr aus dem Meer", description = "Warum unterhaltet Ihr Euch nicht mit Katar, während ich an Eurer Waffe arbeite? Er erwähnte, dass er Hilfe bei Patrouillen am Strand braucht, und mir wäre es lieber, Ihr würdet Euren Geist und Eure Waffen trainieren, anstatt Euch mit den anderen Tunichtguten in diesem Lager zu betrinken.", objectives = "Sprecht mit Katar in den Sümpfen des Elends.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1423] = { title = "Die verlorenen Vorräte", description = "Dieses Fass ist klein, aber stabil. Seine Ritzen sind mit einem gelben, duftenden Wachs versiegelt. Auf der Unterseite des Fasses stehen die Worte:\n\nRÜSTMEISTER LUNGERTZ\n\nBURG NETHERGARDE", objectives = "Bringt die verlorenen Vorräte zu Rüstmeister Lungertz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1424] = { title = "Tränenteich", description = "Der Kriegshäuptling schickt uns, die seltsamen Vorkommnisse im Tempel von Atal'Hakkar zu untersuchen.\n\nDie Trolle des Stammes der Atal'ai sind ein Stamm dunkler Zauberkundiger, die dafür bekannt sind, verbotene Magie auszuüben. Ihr könnt Euch vorstellen, wie erstaunt wir waren, als wir hier eintrafen und feststellten, dass der Tempel versunken war.\n\nDie grünen Großdrachen hüten nun die Stelle und spielen sich als Beschützer von Azeroth auf.\n\nWir müssen herausfinden, was geschehen ist. Forscht rund um den Tränenteich und sammelt Artefakte der Atal'ai. Damit kann ich dieses Rätsel lösen.", objectives = "Fel'Zerul in Stonard möchte, dass Ihr 10 Artefakte der Atal'ai sammelt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1425] = { title = "Überbringen der Lieferung", description = "Während ich diesen Wagen repariere, $N, habe ich eine letzte Aufgabe für Euch.\n\nIch habe die wichtigsten Vorräte eingepackt, die ich vor den Angriffen der Oger retten konnte. Bringt sie zur Burg Nethergarde. Die Burg schmiegt sich an die nördlichen Hügel der verwüsteten Lande und wacht über das Dunkle Portal.\n\nFolgt der Straße nach Osten, um Nethergard zu erreichen. Geht an der Gabelung nach Süden in die verwüsteten Lande und bei der nächsten Gabelung nach links. Folgt der Straße, $N, und seid wachsam.", objectives = "Bringt die Ladung für Nethergarde zu Rüstmeister Lungertz in der Burg Nethergarde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1426] = { title = "Gefahr aus dem Meer", description = "Ich mag weder das Meer noch die Kreaturen, die ich aus seiner Tiefe kommen sah. Es ist eine mächtige, aber blinde Herrin; launisch und brutal. Es wäre mir ein Vergnügen, die Fischmenschen zu Hunderten zu töten, wenn es in meiner Macht stünde. Eine kleine Freude ist es mir wenigstens, sie durch die Hände all derer sterben zu sehen, die den Willen der Horde erfüllen.\n\nUnd damit sind wir bei Euch, $C . Wie viele könnt Ihr besiegen? Würdet Ihr Euch mit dem Mächtigsten ihrer Art messen?", objectives = "Tötet 10 Marschenmurlocs, 10 Marschentintenspucker und 10 Marschenfleischfresser und kehrt dann zu Katar in den Sümpfen des Elends zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1427] = { title = "Gefahr aus dem Meer", description = "Sprecht wieder mit Tok'Kar, bevor Ihr Euch ausruht. Während Ihr fort wart, hat er, glaube ich, ein paar Waffen vollendet. Für Eure Hilfe würde er Euch eine davon anbieten. Ihr tätet gut daran, ihre Kraft an den Fischmenschen zu erproben, wenn Ihr bereit seid ... aber nur, um mich weiterhin zu erfreuen.", objectives = "Sprecht mit Tok'Kar in den Sümpfen des Elends.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1428] = { title = "Fortwährende Gefahr", description = "Freut mich zu sehen, dass Euer Hass auf die Fischmenschen mit meinem wächst.\n\nSucht mehr von ihnen am Strand entlang, und wenn Ihr genug vom Gefecht habt, kommt zu mir zurück. Dann sprechen wir über eine Belohnung für Eure Ausdauer.", objectives = "Tötet 10 Marschentintenspucker, 10 Marschenfleischfresser und 10 Marschenorakel und kehrt dann zu Katar in den Sümpfen des Elends zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1429] = { title = "Der Verbannte der Atal'ai", description = "Während Ihr den Gefahren des Tränenteichs getrotzt habt, kehrte einer meiner Späher mit einer in Blut und auf getrocknetem Fleisch geschriebenen Rolle zurück. Es scheint sich um ein Urteil gegen einen der Priester des Stammes der Atal'ai zu handeln.\n\nDer Priester wurde zu etwas Schlimmerem als dem Tod bei den Atal'ai verurteilt.\n\nEr wurde ins Hinterland zu den Trollen der Witherbark verbannt.\n\nIch bündle diese Artefakte. Ihr müsst den Verbannten suchen und ihren wahren Verwendungszweck herausfinden. Kommt wieder zu mir, wenn Eure Reise beendet ist.", objectives = "Bringt das Artefaktbündel der Atal'ai zu dem Verbannten der Atal'ai ins Hinterland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1430] = { title = "Frischfleisch", description = "Bei meinen Kunden besteht eine enorme Nachfrage nach dem saftigen Geschmack von Kriecherfleisch; besonders nach dem Fleisch der monströsen Kriecher.\n\nWenn Ihr vorhabt, zur Küste zu reisen, könnte es sich lohnen, wenn Ihr mir einige ihrer Beine bringt, damit ich sie nach Orgrimmar transportieren lassen kann.\n\nDie Küste liegt östlich von hier. Ihr solltet keine Probleme haben, die Kreaturen zu finden, die an den Stränden und im Meer umherhuschen.", objectives = "Bringt 10 monströse Kriecherbeine zu Dar in den Sümpfen des Elends.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1431] = { title = "Allianz-Beziehungen", description = "Seid still, $n, und lasst mich Euch etwas Wichtiges über unser Volk sagen, das nicht auf der Hand liegt.\n\nWir sind ein stolzes Volk und der Krieg gegen die Menschen hat selbst Thralls große Geduld auf die Probe gestellt. Wisst Ihr, unser Kriegshäuptling ist weise und umsichtig und sein Volk kommt stets an erster Stelle. Letztendlich ist er ein Diplomat und hat in seiner Zeit bei den Menschen viel von ihrer Art gelernt.\n\nWenn die Geschichte, die ich begonnen habe, Euer Interesse weckt, dann geht zu Keldran beim westlichen Ausgang der Stadt. Dort steht seine Hütte.", objectives = "Sprecht mit Keldran in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1432] = { title = "Allianz-Beziehungen", description = "Wenn die Allianz immer tiefer nach Kalimdor vorstößt, könnten falsche Schlussfolgerungen über mögliche Bündnisse der Horde mit der Brennenden Legion gezogen werden. Dazu darf es der Kriegshäuptling nicht kommen lassen. Und mit seinem Segen übernehme ich die Aufsicht darüber, dass alle Missverständnisse ausgeräumt werden.\n\nIch habe Agenten in der Gegend von Desolace am Geistwandlerposten nördlich des großen Kodofriedhofs. Wenn Ihr vom verbrannten Tal im Steinkrallengebirge aus südwärts geht, solltet Ihr dort vorbeikommen. Wenn Ihr eintrefft, sucht Takata Steelblade auf.", objectives = "Sprecht mit Takata Steelblade in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1433] = { title = "Allianz-Beziehungen", description = "Die Burning Blade haben eigene Ziele verfolgt; doch wisst, dass sie bis ins Mark böse sind und ihr Geist verderbt wurde. Sie zu vernichten ist die einzige Möglichkeit, ihnen Einhalt zu gebieten.\n\nKeldran schickte Maurin mit mir, weil er die Klinge und die Arglist ihrer Hexenmeister kennt.\n\nEr leitet unsere Verschwörungen gegen die Klinge, während ich mich um die anderen dämonischen Bedrohungen in Desolace kümmere.\n\nSprecht mit ihm und er wird Euch in seine Pläne einweihen.", objectives = "Sprecht mit Maurin Bonesplitter in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1434] = { title = "Beschmutzt durch Satyrn", description = "Eine Dämonenplage geschieht nicht ohne andere Einflüsse - etwas anderes ermöglicht dem Bösen, Fuß zu fassen.\n\nEs mag mit einem schwachen Geist beginnen, einer unnötigen Gier nach Macht, möglicherweise Rachedurst oder der Verlockung nach höchster Gerechtigkeit. Wenn der Schmerz uns übermannt, dann nutzt uns das Böse aus - das Böse wie die Satyrn.\n\nBande wurden zwischen ihnen und den Burning Blade geknüpft und Thrall hätte sie getötet. Sucht sie nordöstlich von hier und kommt zu mir zurück, wenn Ihr sie zurückgeschlagen habt.", objectives = "Besiegt 7 Schurken der Zornsäer, 7 Teufelsanbeter der Zornsäer, 7 Verräter der Zornsäer sowie 7 Höllenrufer der Zornsäer und kehrt zu Takata Steelblade in Desolace zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1435] = { title = "Brennender Geist", description = "Für diese abscheulichen Kreaturen, die ihrem Lehen aus so egoistischen Gründen den Rücken kehren, ist der Tod höchst wünschenswert. Doch wenn man es mit denen zu tun hat, die sich der Dunkelheit verschrieben haben, reicht der Tod allein nicht aus.\n\nNehmt diesen Edelstein. Wenn einer der Burning Blade dem Tode nahe ist, aktiviert seine Magie. Der Zauber wird den verderbten Geist aus seinem Opfer herausziehen und einen damit erfüllten Edelstein hinterlassen.\n\nBringt mir diese erfüllten Edelsteine, damit ich sie angemessen entsorgen kann.\n\nGeht jetzt, und möge Euch der Tod meiden.", objectives = "Bringt den brennenden Edelstein und 15 erfüllte brennende Edelsteine nach Desolace zu Maurin Bonesplitter.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1436] = { title = "Allianz-Beziehungen", description = "Der Kampf läuft gut, $n. Vielleicht lässt uns der Kriegshäuptling, bevor die Jahreszeiten wechseln, in unsere Heimat zurückkehren, wenn der Kampf gegen die Dämonen und ihre Unterlinge weiterhin so gute Fortschritte macht.\n\nKehrt zu Keldran zurück und lasst ihn wissen, was wir getan haben. Ich bin sicher, er belohnt Euch für Eure Taten hier. Seine Sache ist ihm wichtig und es wird ihn mit Stolz erfüllen, wenn er weiß, dass der Kriegshäuptling seine Sorgen respektiert.", objectives = "Sprecht mit Keldran in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1437] = { title = "Vahlarriels Suche", description = "Ich bin Vahlarriel, $n. Ich kam her, um mich nach dem Befinden zweier vermisster Adliger einer Kaufmannsfamilie aus Darnassus zu erkundigen - Haus Malem. Der Vater des Hauses fürchtet das Schlimmste. Ich soll tun, was ich kann, um seine vermissten Kinder zu finden. Ich habe noch nicht mit der Suche nach Tyranis und Dalinda begonnen, hoffe aber, ich werde mich nicht lange hier aufhalten.\n\nZuletzt hörte man, dass sie vor wenigen Wochen durch das Steinkrallengebirge gekommen sein sollen.\n\nFalls Ihr ihren Wagen findet, sucht mich bitte unverzüglich auf.", objectives = "Sucht und findet den Wagen von Tyranis und Dalinda Malem in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1438] = { title = "Vahlarriels Suche", description = "Sucht Dalinda und Tyranis, wenn Ihr könnt, und berichtet mir von Euren Funden. Beginnt Eure Suche in dieser Festung. Ich setze mich sofort mit meinen Vorgesetzten in Darnassus in Verbindung und informiere sie über die Situation.\n\n$N, ich möchte Euch noch etwas wissen lassen. Meine Vorgesetzten haben Besorgnis wegen Tyranis und seinen Motiven für diese Reise geäußert. Es ist ihnen wichtiger, dass Dalinda gefunden und wohlbehalten zurückgebracht wird. Tyranis soll ... gefesselt werden, ehe man ihn nach Hause bringt.", objectives = "Sucht Dalinda Malem in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1439] = { title = "Suche nach Tyranis", description = "Wir wurden hierher gebracht, nachdem die Orcs alle unsere Wachen und Diener abgeschlachtet hatten. Oh, was haben sie ihnen Schreckliches angetan! Ich dachte, sie würden uns auf der Stelle töten, doch dann wurde deutlich, dass sie andere Pläne hatten.\n\nTyranis versuchte, mit ihnen zu reden. Ich glaube, er wollte sie mit seinem arkanen Wissen beeindrucken ... Ich bin nicht sicher, warum.\n\nBitte, ich kann hier nicht weg, bevor ich weiß, was meinem Bruder zugestoßen ist. Sucht ihn und kommt zu mir, wenn Ihr sein Schicksal kennt.", objectives = "Sucht Tyranis Malem in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1440] = { title = "Rückkehr nach Vahlarriel", description = "Also ist die Zeit gekommen? Ich weiß Eure Bemühungen zu schätzen, und wenn auch die Situation dafür nicht geeignet ist, lasst mich Euch jetzt für alles danken, was Ihr für mich und meine Familie getan habt. Wenn Ihr bereit seid, hier hält mich nichts mehr - wir können aufbrechen, falls es Euch passend erscheint.", objectives = "Begleitet Dalinda Malem aus der Festung Thunder Axe und kehrt zu Vahlarriel Demonslayer nach Desolace zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1442] = { title = "Suche nach dem Kor-Edelstein", description = "Seid gegrüßt, $N. Was kann ich für einen tun, der dem heiligen Weg folgt?\n\nAh ja, Stilwell, der Schmied... das war vor langer Zeit. Ich erinnere mich gut an ihn, doch ich habe seinen Namen schon eine ganze Weile nicht mehr gehört.\n\nEr schien mir nie ein habgieriger Mann zu sein, daher kann ich nur davon ausgehen, dass sein Wunsch nach einem Kor-Edelstein edle Motive hat.\n\nWenn Ihr wirklich so einen Edelstein möchtet, dann müsst Ihr in den Nordwesten von Ashenvale. Dort findet Ihr die Blackfathom-Tiefe mit einigen alten Ruinen. Die Naga, die diese Edelsteine noch immer benutzen, sind dort unten. Geht nicht allein, $C.", objectives = "Bringt einen Kor-Edelstein zu Thundris Windwirker in Dunkelküste.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1444] = { title = "Rückkehr zu Fel'Zerul", description = "Jammal'an der Prophet verbannte mich aus dem Tempel von Atal'Hakkar. Einst empfand ich den Hohepriester als würdigen Anführer.\n\nSein unerschütterlicher Glaube an seine Prophezeiung wird den Untergang der Atal'ai herbeiführen. Wenn es nicht schon geschehen ist.\n\nAls ich meiner Besorgnis Ausdruck verlieh, hieß man mich einen Ungläubigen und verstieß mich aus dem Tempel.\n\nDie Artefakte, die Ihr zu mir brachtet, sind harmlos. Aber wenn Jammal'an die richtige Fetischverzauberung für das Beschwörungsritual gefunden hat, droht der Welt große Gefahr...", objectives = "Kehrt zu Fel'Zerul in Stonard zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1445] = { title = "Der Tempel von Atal'Hakkar", description = "Also sprach er von Jammal'ans Prophezeiung?\n\nDer spirituelle Anführer der Atal'ai glaubt, wenn Hakkar aus dem Nether nach Azeroth zurückkehrt, wird der Gott dem Stamm der Atal'ai Unsterblichkeit gewähren.\n\nTörichte Arglist, um den Jüngsten Tag schneller herbeizuführen, wenn Ihr mich fragt.\n\nDoch Ihr sagt, der Verbannte sprach von verzauberten Fetischen? Das erfüllt mich mit großer Sorge. Wenn sie wahrhaftig der Schlüssel zu dem Ritual der Atal'ai sind, das dieses Durcheinander verursachte, müssen wir die Mächte verstehen, die in ihnen wohnen.\n\nBegebt Euch in den Tempel und werdet dieser Fetische habhaft!", objectives = "Sammelt 20 Fetische von Hakkar und bringt sie zu Fel'Zerul in Stonard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1446] = { title = "Jammal'an der Prophet", description = "Meine Gefährten aus Witherbark mögen keine Fremden in ihrer Nähe.\n\nIch? Ich habe keine Heimat mehr. Mein Volk, der große Stamm der Atal'ai aus den Sümpfen des Elends, hat mich verbannt.\n\nJammal'an, unser spiritueller Anführer, hatte eine, wie wir uns ausdrücken, Prophezeiung. Er glaubt, die Beschwörung des Gottes Hakkar bringt den Atal'ai Unsterblichkeit.\n\nIch jedoch drängte auf Vorsicht. Wenn die Prophezeiung nun nichts weiter als Manipulation war?\n\nIch will Rache für meine Verbannung. Bringt mir Jammal'ans Kopf. Vielleicht ist mein Volk dann frei.", objectives = "Der Verbannte der Atal'ai im Hinterland möchte den Kopf von Jammal'an.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1447] = { title = "Der vermisste Diplomat", description = "Ja, $C, Ihr seid offenkundig nicht einer der Klügsten Eurer Art, der je nach Stormwind kam, aber einer der Dümmsten, wenn Ihr nicht wieder fortgeht.\n\nHabt Ihr meine Freunde getroffen?", objectives = "Besiegt Dashel Stonefist in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
